const top_irelia = {
  champion: '이렐리아',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 미니언을 활용해 (Q)\'칼날 쇄도\'로 스택을 쌓으며 가렌의 (Q)\'결정타\' 사거리에 들어가지 않도록 주의하세요. 가렌이 (Q)\'결정타\'를 사용해 침묵을 걸며 달려들면 거리를 벌려 가렌의 공격을 피하세요.', lv3: '가렌이 (W)\'용기\'를 사용해 보호막을 얻었을 때는 딜교환을 피하고 스킬이 빠진 뒤에 진입하세요. (E)\'쌍검협무\'로 가렌을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 공격하는 것이 좋아요. (Q)\'결정타\'의 침묵을 맞지 않도록 조심하세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례해 피해를 주니 체력이 낮을 때는 빠르게 물러나세요. (R)\'선봉진격검\'을 적중시켜 가렌을 불안정 상태로 만든 뒤 (Q)\'칼날 쇄도\'로 진입하되, (Q)\'결정타\'는 둔화를 제거하니 결계 둔화에만 기대지 마세요. 가렌의 (E)\'심판\' 피해를 (W)\'저항의 춤\'으로 버티며 정글러와 협력하세요.', item: '몰락한 왕의 검을 첫 코어로 가면 공격 속도와 생명력 흡수로 전투를 이어가기 편해요. 신발은 가렌의 기본 공격으로부터 받는 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 추가 피해를 입혀 체력이 낮은 가렌을 빠르게 마무리하세요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 미니언 뒤에 숨어도 맞을 수 있음을 주의하세요. (Q)\'칼날 쇄도\'를 미니언에 사용해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으며 파밍하세요. 근접 공격에 (P)\'불의 심판\'이 붙으므로 무리한 평타 교환은 피해요.', lv3: '(E)\'화약통\' 근처에서 싸우면 폭발 시 둔화와 피해를 입으니 통이 깔린 위치를 확인하고 움직이세요. 갱플랭크의 (W)\'괴혈병 치료\'가 빠진 것을 확인한 뒤 (E)\'쌍검협무\'로 기절을 시키고 (Q)\'칼날 쇄도\'로 진입해 몰아붙이세요. (W)\'저항의 춤\'을 사용해 갱플랭크의 물리 피해를 줄이며 싸우는 것도 좋아요.', lv6: '갱플랭크의 (R)\'포탄 세례\' 범위에 들어가면 둔화와 피해를 입으니 포격 구역 밖으로 빠르게 벗어나세요. (R)\'선봉진격검\'으로 적들을 불안정 상태로 만든 뒤 (Q)\'칼날 쇄도\'를 연달아 사용해 순식간에 체력을 깎으세요. (W)\'괴혈병 치료\'로 회복하기 전에 최대한 많은 피해를 입히는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄이면 킬을 따기 훨씬 쉬워져요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'를 사용하여 둔화와 피해를 입히며 (P)\'서비스 시간\'으로 체력을 회복해요. 미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 쌓으며 막타를 챙기세요. 술통은 오래 남을수록 피해와 둔화가 커지니 굴러온 술통 범위에서 빠르게 벗어나세요.', lv3: '그라가스의 (E)\'몸통 박치기\'가 닿지 않는 위치에서 미니언을 활용해 스택을 쌓으세요. 그라가스가 (W)\'취중 분노\'를 켜서 받는 피해를 줄이는 동안에는 무리하게 진입하지 마세요. (E)\'쌍검협무\'로 그라가스를 기절시키면 (Q)\'칼날 쇄도\'로 빠르게 진입해 딜교환을 시도하세요.', lv6: '그라가스의 (R)\'술통 폭발\'에 맞으면 폭발 지점에서 멀리 밀려나 진입 흐름이 끊기니, 궁극기가 빠진 직후에 다시 붙으세요. (E)\'몸통 박치기\'를 먼저 쓴 그라가스에게는 (R)\'선봉진격검\'을 맞히고 (Q)\'칼날 쇄도\'로 붙어 킬각을 노려보세요. 정글러와 함께 싸울 때는 (E)\'쌍검협무\'의 기절로 그라가스의 움직임을 끊으세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 그라가스의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 가고 몰락한 왕의 검으로 전투력을 높이세요.', spell: '점멸과 점화를 추천해요. 그라가스의 (P)\'서비스 시간\'을 통한 체력 회복 효과를 줄이기 위해 점화가 필요해요.' },
    '그웬': { lv1: '그웬은 평타의 (P)\'가위 난도질\'로 체력을 회복하며 압박하려 해요. 1~2레벨에는 (Q)\'싹둑싹둑!\'의 중앙 고정 피해를 피하며 짧게 딜교환을 하세요. 미니언에 (Q)\'칼날 쇄도\'를 사용하여 빠르게 진입하고 빠지는 방식으로 거리 조절을 하는 게 좋아요.', lv3: '(W)\'신성한 안개\'는 대상 지정 스킬만 막으므로 (E)\'쌍검협무\'를 던져 그웬을 기절시키는 건 가능해요. (E)\'돌격가위\'로 거리를 좁혀올 때 (E)\'쌍검협무\'를 맞춰 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 중첩을 쌓으세요. 그웬의 (Q)\'싹둑싹둑!\' 가위질 횟수가 적을 때 진입해야 피해를 덜 입어요.', lv6: '(R)\'선봉진격검\'을 맞혀 표식을 남기고 (Q)\'칼날 쇄도\'로 빠르게 진입해 딜교환을 시작하세요. 그웬이 (R)\'바느질\'로 둔화를 걸며 거리를 벌리려 하면 (E)\'쌍검협무\'로 다시 기절시켜 추격해야 해요. (W)\'신성한 안개\'가 켜졌을 때는 대상 지정 공격이 안 되니 안개 속으로 직접 들어가서 싸우세요.', item: '몰락한 왕의 검을 가서 공격 속도와 생명력 흡수로 맞서세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'의 체력 회복을 억제해야 킬각을 잡기 편해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 견제하므로 첫 웨이브에서 무리하게 붙지 마세요. 미니언을 이용해 (Q)\'칼날 쇄도\' 중첩을 쌓으며 진입 기회를 보고, 부메랑이 돌아오는 궤적을 피해 피해를 최소화하세요. (W)\'슝슝\' 추가 피해가 섞인 평타를 계속 맞으면 체력이 금방 소모되니 주의하세요.', lv3: '(E)\'쌍검협무\'를 맞혀 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 딜교환을 마쳐야 해요. 나르가 (E)\'폴짝\'으로 거리를 벌리거나 도망치려 할 때 (Q)\'칼날 쇄도\'로 끝까지 따라붙어 추격하세요. 나르의 분노가 가득 차 메가 나르로 변신하면 (W)\'쿵쾅\' 기절을 조심하며 잠시 거리를 두는 것이 좋아요.', lv6: '(R)\'선봉진격검\'으로 진입해 나르를 둔화시키고 빠르게 몰아쳐 킬각을 잡으세요. 하지만 메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절시키니, 벽 근처에서 싸울 때는 위치 선정에 주의해야 해요. 라인을 적당히 밀어두고 나르가 변신해 무리하게 들어올 때 정글러와 함께 받아치세요.', item: '몰락한 왕의 검으로 공격 속도를 챙기고 체력 비례 피해를 입히세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고 점멸로 (E)\'쌍검협무\'의 변수를 만드세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 막타를 먹을수록 강해지니 미니언 막타를 먼저 가져가세요. (Q)\'칼날 쇄도\'로 미니언을 처치하며 (P)\'아이오니아의 열정\' 중첩을 쌓고 짧게 압박하세요. 무리한 맞교환은 피하고 나서스가 편하게 막타를 먹지 못하게 웨이브를 관리하세요.', lv3: '나서스가 (W)\'쇠약\'을 사용하면 이동 속도와 공격 속도가 점점 느려지니 오래 맞지 않게 주의하세요. (E)\'쌍검협무\'를 맞춰서 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 딜교환을 하고 빠져야 해요. (E)\'영혼의 불길\'이 깔린 지역은 방어력이 낮아지니 그 위에서 오래 싸우지 말고 벗어나세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 방어력이 올라가고 (Q)\'흡수의 일격\' 쿨타임이 줄어드니 정면 승부는 피하세요. (R)\'선봉진격검\'으로 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 몰아쳐서 킬각을 잡는 것이 좋아요. 나서스가 성장하기 전에 라인을 강하게 밀어 포탑 압박을 이어가며 정글의 도움을 유도하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 많은 나서스를 깎고 생명력 흡수로 버티세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초반 교전에서 나서스의 체력 회복 효과를 감소시키며 킬을 노려야 해요.' },
    '녹턴': { lv1: '1~2레벨에는 미니언을 활용해 (P)\'아이오니아의 열정\' 중첩을 쌓으며 전투를 준비하세요. 상대가 (Q)\'황혼의 인도자\'를 던지면 무빙으로 피해를 최소화하며 거리를 조절해요. 초반에는 무리하게 진입하기보다 스택을 모으는 데 집중하는 것이 좋아요.', lv3: '스킬이 모이면 (E)\'쌍검협무\'를 적중시켜 기절을 시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 딜교환을 해요. 상대의 (W)\'어둠의 장막\'이 빠진 것을 확인하고 스킬을 쏟아붓는 것이 중요해요. 적의 보호막에 내 스킬이 막히지 않도록 주의하며 공격하세요.', lv6: '상대가 (R)\'피해망상\'으로 시야를 차단하면 위치를 파악하기 어려우니 주의해야 해요. (W)\'저항의 춤\'을 사용하여 상대의 공격을 받아내며 (R)\'선봉진격검\'으로 역공을 시도하세요. 정글러의 개입에 대비해 라인 관리를 하며 적절한 거리 유지가 필요해요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주며 몰락한 왕의 검은 공격 속도와 생명력 흡수를 제공해요.', spell: '점멸과 점화예요. 점멸로 거리를 조절하고 점화로 적의 체력 회복을 억제하며 킬을 노려요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩과 (Q)\'학살\' 회복력으로 1~2레벨 근접전에서 앞서요. (Q)\'칼날 쇄도\'로 미니언을 타며 거리를 조절하고, 짧게 딜교환한 뒤 빠르게 빠지세요. 출혈 중첩이 쌓이기 전에 교전을 끝내는 리듬이 필요해요.', lv3: '(E)\'포획\'에 끌려가면 (W)\'마비의 일격\' 둔화까지 이어져 위험하니, 사거리 밖에서 (E)\'쌍검협무\'를 먼저 맞춰 기절시키세요. 기절한 적에게 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하고, 다리우스가 (Q)\'학살\'을 쓰면 (W)\'저항의 춤\'으로 물리 피해를 줄여 버티세요. (E)\'포획\'이 빠진 타이밍이 가장 안전하게 몰아칠 수 있는 기회예요.', lv6: '(R)\'선봉진격검\'을 맞춰 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 중첩을 쌓으며 공격하세요. 하지만 (P)\'과다출혈\' 중첩이 높을 때 (R)\'녹서스의 단두대\'를 맞으면 치명적이니, 체력이 낮다면 무리하게 붙지 말고 거리만 유지하세요. 라인을 당겨 포탑 근처에서 (E)\'쌍검협무\' 연계를 노리며 정글의 개입을 기다리는 것이 좋아요.', item: '몰락한 왕의 검을 첫 코어로 선택해 다리우스의 높은 체력을 깎고 생명력 흡수로 버티세요. 신발은 다리우스의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. (Q)\'학살\'을 통한 다리우스의 체력 회복을 억제하고 킬각을 잡을 때 결정적인 피해를 줄 수 있어요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 쏘아 견제하므로 미니언 뒤에 숨어서 피해를 최소화하세요. 1~2레벨에는 무리하게 붙지 말고 (Q)\'칼날 쇄도\'로 미니언을 타며 체력을 관리하고 기회를 엿보세요. 상대의 마나가 많이 소모될 때까지 거리 조절을 하며 경험치를 챙기세요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'을 맞으면 속박되니, 표식이 붙었을 때는 잠시 뒤로 물러나세요. 라이즈의 속박 스킬이 빠진 직후에 (E)\'쌍검협무\'를 맞히고 (Q)\'칼날 쇄도\'로 진입해 몰아붙이세요. (W)\'저항의 춤\'으로 상대의 마법 피해를 줄이면서 딜교환을 마무리하세요.', lv6: '(R)\'선봉진격검\'을 맞춰 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 접근해 폭딜을 넣으세요. 라이즈가 (R)\'공간 왜곡\'으로 아군과 함께 합류하거나 도망갈 수 있으니, 궁극기 사용 후에는 끝까지 추격해 킬을 내야 해요. 라인을 밀어 넣은 뒤 부쉬에 숨어 라이즈가 (W)\'룬 감옥\'을 쓰기 전에 먼저 진입하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수로 지속 싸움을 이끌어내세요. 신발은 마법 저항력을 높이고 속박 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라이즈의 강한 푸쉬력을 따라가고 빠르게 합류하여 운영에서 앞서가세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용하여 근접 거리에서 강한 마법 피해를 입혀요. 미니언에 (Q)\'칼날 쇄도\'를 사용하여 패시브 중첩을 쌓으며 럼블의 사거리 밖에서 움직이세요. 럼블이 열기를 쌓아 위험 상태가 되기 전까지는 무리한 진입을 피해요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하면 피해를 흡수하므로 방패가 사라진 뒤에 진입하세요. (E)\'쌍검협무\'로 럼블을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 접근해 딜교환을 해요. 럼블의 (E)\'전기 작살\'에 맞아 마법 저항력이 감소하지 않도록 주의하며 싸우세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 깔면 그 구역 안에서는 피해를 입고 둔화되니 즉시 피하세요. 럼블의 궁극기가 빠진 뒤에 (R)\'선봉진격검\'으로 표식을 남기며 들어가면 킬을 노릴 수 있어요. 럼블의 궁극기는 광범위한 피해를 주니 라인을 밀고 있을 때 정글러의 위치를 꼭 확인하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 럼블의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블은 짧게 교환하고 빠지는 경우가 많으니 점화의 지속 고정 피해로 체력이 낮아진 럼블을 마무리하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 강하게 압박할 수 있으니 1~2레벨에는 미니언을 이용해 (P)\'아이오니아의 열정\' 중첩을 쌓는 데 집중하세요. 레넥톤이 (Q)\'양떼 도륙\'을 사용하려 할 때 (Q)\'칼날 쇄도\'로 미니언을 타고 거리를 벌리며 대응하세요. 무리하게 맞딜을 하기보다는 스택을 쌓아 기동성을 확보하는 것이 중요해요.', lv3: '레넥톤의 (W)\'무자비한 포식자\' 기절을 맞으면 연계를 그대로 받으니 이 스킬이 빠지기 전에는 (W)\'저항의 춤\'으로 피해를 줄이며 거리를 두세요. 레넥톤이 (E)\'자르고 토막내기\'로 들어오는 타이밍에 (E)\'쌍검협무\'를 맞혀 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 진입해 딜교환을 하세요. 분노가 쌓인 레넥톤의 (W)\'무자비한 포식자\'는 기절 시간이 길어지니 주의하세요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 얻으면 정면 승부는 피하고 (R)\'선봉진격검\'으로 결계를 만들어 거리를 조절하세요. 레넥톤의 (R)\'강신\' 효과가 끝난 뒤에 (E)\'쌍검협무\'로 기절을 맞히고 (Q)\'칼날 쇄도\'를 연계하면 킬을 노릴 수 있어요. 라인 관리를 잘하며 레넥톤이 (E)\'자르고 토막내기\'로 들어올 때 정글러를 부를 준비를 하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 레넥톤의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 줄여 킬각을 잡기 쉬워져요.' },
    '렝가': { lv1: '렝가는 수풀에서 기본 공격으로 도약해 들어올 수 있으니 수풀 근처에서는 거리를 두세요. (Q)\'포악함\'으로 강화된 평타를 맞지 않도록 간격을 조절하며 (Q)\'칼날 쇄도\'로 미니언을 처치해 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. 야성이 쌓이기 전에 짧게 교환하고 빠지세요.', lv3: '3레벨 이후 딜교환 시에는 렝가의 (E)\'올가미 투척\'을 조심하며 (E)\'쌍검협무\'로 먼저 기절을 시키는 것이 좋아요. 렝가가 들어올 때 (W)\'저항의 춤\'을 사용하면 받는 물리 피해를 줄일 수 있어요. 상대의 야성 중첩을 확인하며 싸움의 타이밍을 잡으세요.', lv6: '6레벨 이후 렝가가 (R)\'사냥의 전율\'로 도약하며 들어올 때 (R)\'선봉진격검\'을 사용해 대응하세요. 렝가의 돌진을 예측하여 (Q)\'칼날 쇄도\'로 빠르게 거리를 좁히거나 피하는 것이 중요해요. 라인을 너무 밀어두면 수풀을 활용한 렝가의 기습에 노출될 수 있으니 주의하세요.', item: '판금 장화와 몰락한 왕의 검을 가요. 상대의 기본 공격 피해를 줄이고 생명력 흡수로 버티기 위해서예요.', spell: '점멸과 점화. 렝가의 (W)\'전투의 포효\'로 인한 체력 회복을 억제하고 킬을 내기 위해서예요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 활용해 빠르게 진입하며 (P)\'룬 검\' 피해를 입히니 무리하게 붙지 마세요. 미니언에 (Q)\'칼날 쇄도\'를 사용해 (P)\'아이오니아의 열정\' 중첩을 먼저 쌓은 뒤 짧게 교환하고 빠지세요. 리븐이 마지막 (Q)\'부러진 날개\'로 밀쳐내려 할 때 거리를 조절하며 대응하세요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞으면 일방적으로 공격당하니 이 스킬이 빠진 것을 확인하고 (E)\'쌍검협무\'를 맞히세요. (E)\'용맹\' 보호막이 켜져 있을 때는 강력한 공격을 아끼고 보호막이 사라지는 시점에 (Q)\'칼날 쇄도\'로 진입해 몰아치세요. 리븐의 돌진기가 모두 빠졌을 때가 가장 좋은 공격 기회예요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 공격 사거리가 늘어나고 재사용 시 잃은 체력에 비례한 바람 가르기를 쓸 수 있으니 체력이 낮을 때 주의하세요. (R)\'선봉진격검\'으로 리븐을 둔화시키고 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 접근해 딜교환을 주도하세요. 라인을 밀어 넣고 정글러가 오는 타이밍에 (E)\'쌍검협무\'로 리븐의 도주를 끊어 킬각을 잡으세요.', item: '몰락한 왕의 검을 핵심 아이템으로 선택해 생명력 흡수와 공격 속도로 맞대결 능력을 높이세요. 신발은 판금 장화를 신어 리븐의 기본 공격 피해를 줄이는 것이 좋아요. 이 조합으로 리븐의 폭발적인 물리 피해를 견디며 싸우세요.', spell: '점멸과 점화를 추천해요. 리븐은 돌진기가 많아 붙고 빠지니 점화의 지속 고정 피해로 체력이 낮아진 리븐을 마무리하세요.' },
    '리산드라': { lv1: '리산드라가 (Q)\'얼음 파편\'으로 멀리서 견제하며 둔화를 걸 수 있으니 거리를 조절하며 미니언을 챙기세요. (Q)\'칼날 쇄도\'를 미니언에 사용하여 패시브 중첩을 쌓고 리산드라가 다가오기 전에 준비를 마쳐야 해요. 1~2레벨에는 리산드라의 스킬을 피하며 체력을 보존하는 것이 중요해요.', lv3: '리산드라가 (W)\'서릿발\'로 속박하면 (Q)\'칼날 쇄도\' 같은 돌진은 쓸 수 없지만 (E)\'쌍검협무\'나 (W)\'저항의 춤\'은 사용할 수 있어요. 리산드라가 (E)\'얼음갈퀴 길\'로 도망가려고 하면 (E)\'쌍검협무\'를 맞혀서 흐름을 끊고 진입하세요. 리산드라의 마법 피해를 줄이기 위해 (W)\'저항의 춤\'을 적절한 타이밍에 사용해 주세요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 체력을 회복하면 잠시 기다렸다가 풀린 뒤에 (R)\'선봉진격검\'으로 진입하세요. 리산드라가 나에게 (R)\'얼음 무덤\'을 쓰면 기절 중에는 스킬을 쓸 수 없으니 사거리 안에 오래 서 있지 마세요. 라인을 너무 밀어두면 리산드라의 기습에 노출될 수 있으니 주의하며 운영하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 리산드라의 (W)\'서릿발\'과 (R)\'얼음 무덤\'의 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화는 리산드라가 자신에게 (R)\'얼음 무덤\'을 사용하여 체력을 회복할 때 그 효과를 줄여서 마무리를 도와줘요.' },
    '마스터이': { lv1: '마스터 이는 (E)\'우주류 검술\'의 고정 피해와 (P)\'2연속 공격\' 때문에 초반 평타 교환이 강해요. (Q)\'칼날 쇄도\'로 미니언을 타며 거리를 조절하고, 상대가 무리하게 들어올 때만 짧게 딜교환을 하세요. 정면에서 계속 부딪히기보다 스킬 쿨타임을 활용해 체력 관리에 집중하세요.', lv3: '(E)\'쌍검협무\'로 상대를 기절시켜 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 딜교환을 하세요. 마스터 이가 (Q)\'일격 필살\'을 사용하면 대상으로 지정할 수 없으니, 그 스킬이 빠진 것을 확인하고 공격을 시작하세요. (W)\'명상\'으로 버티려 하면 (W)\'저항의 춤\'으로 물리 피해를 줄이며 상황을 지켜보세요.', lv6: '(R)\'선봉진격검\'의 둔화는 (R)\'최후의 전사\' 상태의 마스터 이에게 통하지 않으니 주의하세요. 대신 (E)\'쌍검협무\'의 기절은 유효하므로, 기절을 맞힌 뒤 빠르게 (Q)\'칼날 쇄도\'로 몰아쳐 킬각을 잡으세요. (Q)\'일격 필살\'은 쓰는 동안 대상으로 지정할 수 없으니, 그 스킬이 빠진 뒤에 정글러와 함께 진입하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 마스터 이의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 방해하고 확실하게 마무리해야 해요.' },
    '마오카이': { lv1: '마오카이는 (P)\'마법 흡수\'를 활용해 기본 공격으로 체력을 회복하며 (Q)\'덤불 주먹\'으로 둔화를 걸고 밀어내요. 1~2레벨에는 미니언에 (Q)\'칼날 쇄도\'를 사용해 (P)\'아이오니아의 열정\' 중첩을 쌓으며 거리 조절을 하세요. 마오카이가 (Q)\'덤불 주먹\'을 쓰려고 할 때 미니언을 통해 거리를 벌리며 안정적으로 파밍하세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'을 사용하면 대상으로 지정할 수 없으므로, 이 스킬이 빠진 것을 확인하고 (E)\'쌍검협무\'로 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 진입하세요. (W)\'뒤틀린 전진\'에 속박을 맞으면 이동이 제한되니 주의하며, 마오카이의 (E)\'묘목 던지기\'가 깔린 수풀 근처에서는 싸움을 피하세요. (E)\'쌍검협무\'를 먼저 맞춰야 (Q)\'칼날 쇄도\'를 연속으로 사용하여 체력을 회복하며 딜교환을 할 수 있어요.', lv6: '마오카이의 (R)\'대자연의 마수\'는 벽이 다가오며 적을 속박하니, 벽이 오는 방향을 보고 옆으로 피하세요. 궁극기가 빠진 직후에는 큰 군중 제어가 줄어드니 (R)\'선봉진격검\'으로 적을 타격하며 몰아붙이세요. 정글러가 마오카이의 (E)\'묘목 던지기\'를 통해 시야를 확보하고 개입할 수 있으니 라인 관리에 신경 쓰세요.', item: '마법 피해가 주력인 마오카이를 상대하므로 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 신발로 가세요. 첫 코어 아이템은 지속적인 전투와 체력 회복에 도움을 주는 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이는 (P)\'마법 흡수\'로 체력을 회복하며 버티는 능력이 좋으므로 점화로 회복 효과를 감소시키며 킬각을 보세요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 크게 줄고 군중 제어에 면역이 되니, 평타나 (Q)\'칼날 쇄도\'로 먼저 피해를 주어 효과를 끈 뒤 압박하세요. (Q)\'공허의 부름\' 침묵 투사체가 날아오는 방향을 확인해 피하며 미니언을 이용해 거리를 좁히세요. 말자하가 스킬을 쓴 직후에 짧게 붙어 교환하세요.', lv3: '(E)\'재앙의 환상\'이 걸린 상태에서 (W)\'공허의 무리\' 공허충까지 소환되면 피해가 심해지니 짧게 딜교환하고 빠지세요. (E)\'쌍검협무\'를 먼저 맞혀 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으세요. 말자하가 (Q)\'공허의 부름\'으로 침묵을 쓰기 전에 빠르게 진입해 공격하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으며 제압 동안에는 (Q)\'칼날 쇄도\' 같은 스킬을 전혀 쓸 수 없으니 주의하세요. (R)\'선봉진격검\'을 먼저 맞혀 표식을 남긴 뒤 빠르게 진입해 킬각을 잡으세요. (P)\'공허 태세\'가 켜져 있으면 기절이 통하지 않으니 평타나 (Q)\'칼날 쇄도\'로 먼저 벗겨낸 뒤 (E)\'쌍검협무\'로 기절시켜 궁극기 사용을 끊으세요.', item: '몰락한 왕의 검으로 공격 속도와 생명력 흡수를 챙겨 유지력을 높이세요. 신발은 마법 저항력을 제공하고 (Q)\'공허의 부름\' 침묵 지속 시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 챙기고, 말자하는 도주기가 없으니 (R)\'선봉진격검\'과 점멸을 조합해 확실한 킬각을 잡으세요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 지속적인 견제를 하는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'가 활성화된 동안에는 평타 교환이 손해니, 방패가 사라진 뒤에 (Q)\'칼날 쇄도\'로 진입해 짧게 딜교환하세요. 초반에는 무리하게 붙기보다 미니언을 통해 체력을 회복하며 거리를 조절하세요.', lv3: '(E)\'쌍검협무\'를 적중시켜 불안정 상태로 만든 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 중첩을 쌓으세요. 말파이트가 (E)\'지면 강타\'를 쓰면 공격 속도가 감소해 평타 효율이 떨어지니, 최대한 스킬을 먼저 뺀 뒤에 붙는 것이 좋아요. (W)\'천둥소리\'의 여진 피해를 피하기 위해 정면에서 오래 머물지 말고 계속 움직이며 공격하세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없고, 맞으면 공중에 떠서 스킬을 쓸 수 없으니 주의하세요. 정글러가 근처에 있을 때 말파이트의 돌진 거리 안에 오래 서 있지 말고, (R)\'선봉진격검\'으로 먼저 표식을 남겨 둔화시키며 거리를 벌리세요. 궁극기가 빠진 말파이트는 위협적이지 않으니 그때 (Q)\'칼날 쇄도\'로 진입해 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 말파이트를 빠르게 깎고 생명력 흡수로 버티세요. 신발은 마법 저항력을 높여 (Q)\'지진의 파편\' 피해를 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인전 이후 팀 교전 합류가 중요하고, (R)\'멈출 수 없는 힘\'의 각도를 피하기 위해 점멸이 꼭 필요해요.' },
    '모데카이저': { lv1: '1~2레벨에는 (Q)\'칼날 쇄도\'로 미니언을 처치하며 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으세요. 모데카이저의 (Q)\'말살\'은 단일 대상에게 맞으면 피해가 커지니 미니언 사이에서 거리를 조절하며 받아내세요. 첫 웨이브를 정리하며 스택을 쌓는 것에 집중하세요.', lv3: '3레벨에는 (E)\'쌍검협무\'로 모데카이저를 기절시켜 딜교환을 시작하세요. 모데카이저의 (E)\'죽음의 손아귀\'에 끌려가지 않도록 주의하며 (W)\'저항의 춤\'을 사용해 들어오는 피해를 줄여야 해요. 모데카이저가 (W)\'불멸\'로 보호막을 두르기 전에 빠르게 (Q)\'칼날 쇄도\'로 몰아붙이세요.', lv6: '모데카이저가 (R)\'죽음의 세계\'를 사용해 끌고 가면 능력치를 일부 뺏기니 조심해야 해요. (R)\'죽음의 세계\' 안에서는 탈출할 수 없으므로 (R)\'선봉진격검\'을 사용해 적을 최대한 빠르게 처치하고 싸움을 끝내세요. 모데카이저의 (E)\'죽음의 손아귀\'가 빠진 타이밍에 정글러를 불러 함께 교전하면 좋아요.', item: '몰락한 왕의 검을 첫 코어로 올려 공격 속도와 생명력 흡수를 챙기세요. 신발은 모데카이저의 마법 피해를 줄이고 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'을 사용하는 모데카이저의 회복을 억제하여 킬을 따내기 쉬워요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'을 던져 현재 체력에 비례한 피해를 주고 둔화를 걸어요. 뼈톱은 처음 맞는 대상에게 적중하니 미니언 뒤에 숨어서 피해를 피하세요. (Q)\'칼날 쇄도\'를 미니언에 활용해 스택을 쌓으며 문도 박사를 상대할 준비를 하세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜면 주변에 지속 피해를 주고 재사용 폭발로 회색 체력을 회복하니, 그동안은 (W)\'저항의 춤\'으로 피해를 줄이거나 거리를 두세요. (P)\'가고 싶은 데로 간다\'가 준비된 상태면 첫 이동 불가 효과에 저항하니, 통이 떨어진 것을 확인한 뒤 (E)\'쌍검협무\'로 기절시키고 (Q)\'칼날 쇄도\'로 진입하세요.', lv6: '(R)\'최대 투여량\'을 쓴 문도 박사는 체력을 크게 회복하니 궁극기가 빠진 것을 확인하고 진입하세요. (R)\'선봉진격검\'으로 표식을 남기면 (Q)\'칼날 쇄도\'를 연속해서 사용할 수 있어요. 문도 박사가 (P)\'가고 싶은 데로 간다\'로 떨어뜨린 통을 주워 체력을 회복하지 못하게 조심하세요.', item: '문도 박사의 마법 피해를 견디기 위해 헤르메스의 발걸음을 신으세요. 첫 코어 아이템은 체력이 많은 상대를 상대하기 좋은 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 점화는 문도 박사의 체력 회복 효과를 줄여서 킬을 내는 데 도움을 줘요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 조준해 멀리서 견제하며 거리를 벌려요. 미니언을 활용해 (P)\'아이오니아의 열정\' 중첩을 쌓으며 다가갈 준비를 하세요. 견제를 많이 맞았다면 무리하게 붙지 말고 미니언을 받아먹으며 기회를 기다려요.', lv3: '(E)\'퍼붓는 화살\'로 인해 (Q)\'칼날 쇄도\'의 회복 효과가 줄어들 수 있으니 주의하세요. (E)\'쌍검협무\'를 먼저 맞춰 바루스를 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입하세요. 바루스가 (W)\'역병 화살\'의 역병을 터뜨리기 전에 붙어서 싸워야 해요.', lv6: '(R)\'부패의 사슬\'에 맞으면 이동이 차단되어 접근이 어려워지니 조심하세요. (R)\'선봉진격검\'을 적중시켜 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 연달아 들어가면 킬각을 잡을 수 있어요. 적의 기술을 잘 피하며 정글러를 불러 함께 압박하세요.', item: '몰락한 왕의 검을 첫 코어로 가면 체력 비례 피해와 생명력 흡수로 전투를 지속하기 좋아요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 견제 사거리를 빠르게 뚫고 접근하세요.' },
    '베인': { lv1: '1~2레벨에는 미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으세요. 베인이 (W)\'은화살\'을 발동시키기 위해 다가올 때 거리를 조절하며 대응해야 해요. 미니언을 타고 이동하며 베인의 공격 범위를 벗어나세요.', lv3: '(E)\'쌍검협무\'를 적중시켜 베인을 기절시키고 (Q)\'칼날 쇄도\'로 진입하여 딜교환을 시작하세요. 베인이 (Q)\'구르기\'를 사용해 뒤로 빠지려 할 때 (Q)\'칼날 쇄도\'의 재사용 대기시간을 활용해 따라붙으세요. 베인이 (E)\'선고\'로 밀쳐내기 전에 스킬을 먼저 맞히는 것이 중요해요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\'를 쓸 때마다 투명해지니 주의해야 해요. (R)\'선봉진격검\'을 맞춰 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 바로 붙고, 베인이 결계를 지나 빠지려 하면 둔화되니 그때 따라붙으세요. 베인의 (E)\'선고\'에 밀려 지형에 부딪히면 기절하므로 벽 근처에서의 교전을 조심하세요.', item: '몰락한 왕의 검을 첫 코어로 올려 공격 속도와 생명력 흡수를 확보하세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 거리를 벌리려 할 때 점멸로 접근하여 빠르게 제압하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 접근해 기절시키고 (W)\'광란의 상처\'로 피해를 입혀요. (Q)\'번개 강타\'가 빠지기 전까지는 무리하게 붙지 말고 (Q)\'칼날 쇄도\'로 미니언을 타며 거리를 유지하세요. 초반 평타 교환은 볼리베어가 강하니 짧게 치고 빠지는 교환을 반복하세요.', lv3: '(E)\'쌍검협무\'를 맞혀 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 공격하세요. 볼리베어가 (E)\'천공 분열\'을 사용해 보호막을 얻고 둔화를 거는 지역에서는 가급적 벗어나세요. (W)\'광란의 상처\' 표식이 남은 상태에서 계속 싸우면 볼리베어가 체력을 회복하니 표식이 사라진 뒤에 다시 진입하세요.', lv6: '(R)\'선봉진격검\'으로 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 중첩을 쌓고 딜교환하세요. (R)\'폭풍을 부르는 자\'는 포탑을 비활성화하며 도약하니 포탑 근처에서 너무 안심하지 마세요. 볼리베어가 착지하며 거는 둔화는 금방 풀리니, 착지 직후에 (E)\'쌍검협무\'로 기절을 맞혀 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 높은 체력을 가진 볼리베어에게 더 많은 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'광란의 상처\'의 체력 회복 효과를 감소시켜 킬각을 잡기 쉽게 만들어요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제하니 미니언을 이용해 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. 미니언을 (Q)\'칼날 쇄도\'로 타고 다니며 블라디미르의 (Q)\'수혈\'에 맞춰 거리 조절을 하는 것이 중요해요. 초반에는 무리하게 싸우기보다 미니언 막타를 챙기며 성장에 집중하세요.', lv3: '(E)\'쌍검협무\'로 기절을 시키려 할 때 블라디미르가 (W)\'피의 웅덩이\'를 사용하면 딜교환이 끊기니 주의하세요. 블라디미르의 (E)\'선혈의 파도\'는 미니언 뒤에 숨으면 피해를 줄일 수 있으니 위치 선정을 잘해야 해요. (Q)\'칼날 쇄도\'로 빠르게 접근하여 (P)\'아이오니아의 열정\' 최대 중첩 상태에서 몰아붙이세요.', lv6: '블라디미르가 (R)\'혈사병\'을 쓰면 감염된 동안 받는 피해가 늘어나니 그 구역에서 오래 교전하지 마세요. 블라디미르의 (W)\'피의 웅덩이\'가 빠진 직후에 (R)\'선봉진격검\'을 맞혀 피해를 쌓으면 킬각을 잡을 수 있어요. 라인을 빠르게 밀어 넣고 정글러를 불러 블라디미르를 압박하세요.', item: '헤르메스의 발걸음을 구매하여 마법 저항력을 확보하세요. 몰락한 왕의 검을 첫 코어로 올려서 전투 지속력을 높여야 해요.', spell: '점멸과 점화를 추천해요. 점화로 블라디미르의 (Q)\'수혈\'을 통한 체력 회복을 억제해야 해요.' },
    '뽀삐': { lv1: '1~2레벨에는 (Q)\'칼날 쇄도\'로 미니언을 타며 패시브 스택을 쌓으세요. 뽀삐가 (Q)\'망치 강타\'로 바닥을 내려치면 둔화 지대가 생기니 빠르게 벗어나야 해요. 뽀삐가 방패를 던져 (P)\'강철의 외교관\' 보호막을 얻으려 할 때 짧게 평타를 섞어 딜교환하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 (Q)\'칼날 쇄도\' 돌진이 막히고 둔화되니 이 스킬이 빠진 것을 확인하고 진입하세요. 먼저 (E)\'쌍검협무\'를 맞춰 기절시킨 뒤에 들어가야 뽀삐의 반응 속도를 늦출 수 있어요. 벽 근처에 있으면 (E)\'용감한 돌진\'에 맞고 기절할 수 있으니 항상 라인 중앙 쪽으로 자리를 잡으세요.', lv6: '(R)\'선봉진격검\'으로 표식을 남겨 진입하되 뽀삐가 (R)\'수호자의 심판\'으로 멀리 날려버리지 않게 주의하세요. 뽀삐의 궁극기가 빠진 뒤에는 (Q)\'칼날 쇄도\'를 자유롭게 쓰며 몰아붙일 수 있어요. 정글러가 올 때 (E)\'쌍검협무\'로 적을 묶어주며 함께 공격하세요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 뽀삐의 높은 체력을 깎기 위해 몰락한 왕의 검이 좋고, 뽀삐의 물리 피해를 줄이려면 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 뽀삐는 체력이 낮아질수록 방어력이 늘어 단단해지니 점화의 지속 고정 피해로 마무리하세요.' },
    '사이온': { lv1: '사이온이 (E)\'학살자의 포효\'를 사용하면 미니언이 밀려나며 뒤의 적까지 맞고 방어력이 낮아지니 미니언 뒤에 서지 마세요. (Q)\'칼날 쇄도\'로 미니언을 타고 이동하며 (P)\'아이오니아의 열정\' 중첩을 쌓아 패시브 효과를 활용하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 동작이 보이면 직선에서 벗어나 옆으로 움직여 피하세요.', lv3: '사이온이 (W)\'영혼의 용광로\'로 보호막을 켜면 피해가 흡수되니 보호막이 사라질 때까지 기다리세요. (E)\'쌍검협무\'를 먼저 맞춰서 사이온을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입하면 딜교환을 이끌어낼 수 있어요. 사이온의 (Q)\'대량 학살 강타\' 충전 동작이 보이면 옆으로 움직여서 피하세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'을 사용해 돌진해오면 일직선 경로에서 벗어나 옆으로 피하세요. (R)\'선봉진격검\'을 사용하여 사이온에게 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 적중시켜 체력을 회복하세요. 사이온이 사망한 뒤 (P)\'영광스러운 죽음\' 상태로 반격할 수 있으니 처치 후 바로 거리를 벌려야 해요.', item: '몰락한 왕의 검을 첫 코어로 구매해 공격 속도와 생명력 흡수를 챙기세요. 신발은 사이온의 (Q)\'대량 학살 강타\'와 (R)\'멈출 수 없는 맹공\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화. 사이온은 체력이 매우 높은 챔피언이라 마무리 피해를 입히기 위해 점화가 필요해요.' },
    '사일러스': { lv1: '사일러스는 (P)\'페트리사이트 폭발\'이 충전되면 평타 피해가 강해지니 거리를 조절하세요. 미니언에게 (Q)\'칼날 쇄도\'를 맞춰 (P)\'아이오니아의 열정\' 중첩을 쌓으며 파밍하세요. (Q)\'사슬 후려치기\'의 폭발 지점을 피하며 미니언을 활용해 스택을 관리해요.', lv3: '사일러스가 (W)\'국왕시해자\'로 들어오며 체력을 회복할 때 (W)\'저항의 춤\'을 써서 피해를 줄이세요. (E)\'도주 / 억압\'의 사슬을 맞기 전에 (E)\'쌍검협무\'를 던져 사일러스의 행동을 끊는 것이 중요해요. 사일러스의 (Q)\'사슬 후려치기\'가 빠진 시점에 (Q)\'칼날 쇄도\'로 진입해 딜교환을 하세요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'선봉진격검\'을 훔쳐 쓸 수 있으니 주의하세요. 사일러스의 (W)\'국왕시해자\' 회복을 견제하며 (Q)\'칼날 쇄도\'로 빠르게 표식을 남겨 싸우세요. 정글러가 근처에 있다면 사일러스가 (E)\'도주 / 억압\'을 사용해 도망가지 못하도록 (E)\'쌍검협무\'를 맞춰주세요.', item: '몰락한 왕의 검을 첫 코어로 가서 지속 싸움을 준비하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 사일러스의 (W)\'국왕시해자\' 체력 회복 효과를 줄여주세요.' },
    '세주아니': { lv1: '1~2레벨에는 세주아니의 (W)\'혹한의 서릿발\' 둔화를 주의하며 (Q)\'칼날 쇄도\'로 짧게 치고 빠지세요. 상대의 (Q)\'혹한의 맹습\'이 빠진 타이밍에 진입해 기본 공격으로 스택을 쌓으며 압박하세요. 미니언을 이용해 (Q)\'칼날 쇄도\' 초기화를 노리며 체력을 깎아두는 것이 좋아요.', lv3: '(E)\'쌍검협무\'를 먼저 적중시켜 상대를 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 공격하세요. 세주아니의 (Q)\'혹한의 맹습\'이나 (W)\'혹한의 서릿발\'로 인한 (E)\'만년 서리\' 기절을 피하기 위해 거리를 조절하는 것이 중요해요. 상대의 진입 시 (W)\'저항의 춤\'으로 물리 피해를 줄이며 턴을 넘기세요.', lv6: '(R)\'선봉진격검\'을 맞춰 상대를 불안정 상태로 만든 뒤 (Q)\'칼날 쇄도\'로 추격하며 킬각을 잡으세요. 세주아니의 (R)\'빙하 감옥\'은 사거리가 매우 길고 맞으면 기절하니 무빙으로 먼저 피하는 데 신경 쓰세요. 기절 중에는 스킬을 쓸 수 없으니 라인을 밀 때 세주아니의 위치를 계속 확인하세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가세요. 체력이 많은 상대를 효과적으로 공격하고 강인함으로 기절 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 세주아니의 체력 회복 수단이 없으므로 점화의 마무리 피해로 킬을 내기 좋아요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 사용하여 이동 속도가 빨라진 상태로 접근하며 강력한 기본 공격을 가해요. (Q)\'칼날 쇄도\'를 미니언에 사용하여 스택을 쌓고 세트의 평타 사거리 밖에서 움직이며 대응하세요. 초반에는 무리하게 붙기보다 미니언을 활용해 거리 조절을 하는 것이 좋아요.', lv3: '세트의 (E)\'안면 강타\'는 양옆의 적을 끌어당겨 기절시키니 미니언 사이에 끼어있지 않도록 주의하세요. 세트가 (W)\'강펀치\'를 사용해 보호막과 큰 피해를 입히기 전에 (E)\'쌍검협무\'로 먼저 기절을 시키면 딜교환을 주도할 수 있어요. 세트의 투지가 가득 찼을 때 맞붙는 것은 피하는 것이 좋아요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 공중으로 던지면 제압 상태가 되어 아무것도 할 수 없으니 조심하세요. (R)\'선봉진격검\'을 사용해 세트와 주변 미니언에게 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 전투를 치러야 해요. 세트가 (W)\'강펀치\'를 쓰기 위해 피해를 모으는 동안은 거리를 유지하며 정글러의 도움을 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 세트의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 세트의 (P)\'투기장의 투지\'를 통한 체력 회복 효과를 줄일 수 있어요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 입히며 딜교환을 시도해요. 미니언을 (Q)\'칼날 쇄도\'로 타고 다니며 (P)\'아이오니아의 열정\' 중첩을 쌓아 공격 속도를 확보하세요. 쉔이 (Q)\'황혼 강습\'을 사용해 기의 검을 불러올 때 무리하게 붙지 말고 거리를 조절해요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼치면 결계 안의 쉔에게 기본 공격이 막히니, 그동안은 (Q)\'칼날 쇄도\'나 (E)\'쌍검협무\' 같은 스킬 위주로 피해를 주세요. 쉔의 (E)\'그림자 돌진\' 도발을 맞지 않도록 주의하며 (E)\'쌍검협무\'로 먼저 기절을 맞히는 것이 중요해요. 도발이 빠진 타이밍에 (W)\'저항의 춤\'을 켜고 딜교환을 하면 피해를 줄이며 싸울 수 있어요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인에 합류하려 하면 빠르게 라인을 밀어 압박하세요. 쉔의 체력이 낮을 때 (R)\'선봉진격검\'으로 표식을 남기고 (Q)\'칼날 쇄도\'를 초기화하며 몰아붙이면 킬을 노릴 수 있어요. 쉔이 (P)\'기 보호막\'을 얻기 전의 타이밍을 노려 (E)\'쌍검협무\'를 맞히는 것이 핵심이에요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (P)\'기 보호막\'을 두르기 전에 점화를 사용하여 마무리 피해를 입히세요.' },
    '쉬바나': { lv1: '1~2레벨 구간에서는 (P)\'아이오니아의 열정\' 중첩을 쌓는 것에 집중해요. 상대의 (Q)\'잉걸불 일격\'에 맞지 않도록 미니언 사이에서 거리 조절을 하며 파밍을 해요. 무리한 진입보다는 안정적으로 성장하는 것을 우선해요.', lv3: '스킬이 모이면 (E)\'쌍검협무\'로 적을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해요. 상대가 (W)\'지옥불 방패\'를 사용하면 보호막이 사라질 때까지 기다렸다가 싸워요. (W)\'저항의 춤\'을 사용하여 상대의 물리 피해를 줄이며 딜교환을 해요.', lv6: '상대가 (R)\'용의 강림\'을 사용하여 도약할 때 (R)\'선봉진격검\'으로 대응하며 위치를 잡아요. (E)\'쌍검협무\'나 (R)\'선봉진격검\'으로 표식을 남긴 뒤 (Q)\'칼날 쇄도\'를 연속해서 사용하면 킬을 노릴 수 있어요. (E)\'용암 분출\'에 의한 둔화 효과를 조심하며 라인을 관리해요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가요. 몰락한 왕의 검은 생명력 흡수를 제공하고 헤르메스의 발걸음은 마법 저항력을 제공해요.', spell: '점멸과 점화. 점멸로 거리를 좁히고 점화로 부족한 피해를 보충해요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 원거리 견제를 하며 (P)\'굶주린 새떼\'로 체력을 회복해요. 미니언을 통해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓고 (Q)\'칼날 쇄도\'로 진입해 짧게 딜교환을 하세요. 초반에는 스웨인의 견제 피해를 최소화하며 경험치 이득을 보는 것이 중요해요.', lv3: '(E)\'속박명령\'의 파동이 돌아오며 속박하고 끌어당길 수 있으니 파동의 궤적을 보고 옆으로 피하세요. (E)\'속박명령\'이 빠진 타이밍에 (E)\'쌍검협무\'를 맞춰 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하세요. (W)\'저항의 춤\'을 사용해 스웨인의 (Q)\'죽음의 손길\' 마법 피해를 줄이며 버티는 것도 방법이에요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변에서 체력을 흡수하니 무리하게 오래 붙어 있지 마세요. (R)\'선봉진격검\'으로 표식을 남겨 둔화시킨 후 (E)\'쌍검협무\'와 연계해 빠르게 체력을 깎아야 해요. 스웨인은 이동기가 없으니 (W)\'제국의 눈\' 시야 밖에서 정글러를 불러 함께 노리면 효과적이에요.', item: '몰락한 왕의 검을 첫 코어로 선택해 생명력 흡수와 피해량을 챙기세요. 신발은 (E)\'속박명령\'의 속박 지속시간을 줄여주는 헤르메스의 발걸음이 적당해요.', spell: '점멸과 점화를 추천해요. (R)\'악의 승천\'과 (P)\'굶주린 새떼\'를 통한 스웨인의 강력한 체력 회복을 억제해야 처치할 수 있어요.' },
    '스카너': { lv1: '미니언에게 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으며 파밍해요. 상대가 (Q)\'부서진 대지/지반 돌출\'로 강화된 기본 공격을 가해 둔화시키지 못하도록 거리를 조절하세요.', lv3: '(E)\'쌍검협무\'를 적중시켜 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하세요. 상대가 (E)\'이쉬탈의 격돌\'을 사용해 벽으로 밀쳐 기절시키지 못하도록 벽에서 멀리 떨어져 싸우는 것이 중요해요. (W)\'대지의 수호자\'의 보호막이 빠진 타이밍에 딜교환을 시도하세요.', lv6: '(R)\'선봉진격검\'으로 표식을 남긴 후 (Q)\'칼날 쇄도\'를 연달아 사용하며 강하게 압박해요. 상대가 (R)\'꿰뚫기\'로 제압하여 적 진영으로 끌고 가지 않도록 거리 유지를 하며 신중하게 진입하세요. 정글러가 올 때 (R)\'선봉진격검\'의 결계 둔화로 스카너의 이동을 늦추면 좋아요.', item: '몰락한 왕의 검과 판금 장화를 선택해요. 체력이 높은 상대를 빠르게 깎아내고 기본 공격 피해를 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. 상대의 체력이 낮을 때 확실한 마무리 피해를 입히기 위해서예요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 사용하며 라인을 밀 때 미니언을 이용해 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. 독구름 안에서 싸우기보다 미니언을 타고 (Q)\'칼날 쇄도\'로 빠르게 움직이며 거리를 조절하세요.', lv3: '신지드가 (W)\'초강력 접착제\'를 던지면 그 위에서는 (Q)\'칼날 쇄도\'를 사용할 수 없으니 주의하세요. (E)\'쌍검협무\'로 적을 기절시킨 뒤 진입하여 딜교환을 하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 켜고 (Q)\'맹독의 자취\'로 고통스러운 상처를 남기면 정면 대결을 피하세요. (R)\'선봉진격검\'으로 적에게 표식을 남긴 뒤 (Q)\'칼날 쇄도\'를 연속해서 사용하여 신지드를 몰아붙이세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 전투 지속력을 높이세요. 신발은 (Q)\'맹독의 자취\'의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 신지드의 움직임에 맞춰 대응하고 거리를 조절하세요.' },
    '아이번': { lv1: '미니언에게 (Q)\'칼날 쇄도\'를 적중시켜 (P)\'아이오니아의 열정\' 중첩을 쌓으며 파밍해요. 아이번의 (Q)\'덩굴뿌리\'는 처음 맞은 적을 속박하므로 미니언 뒤에 숨어 스킬을 피하며 거리를 조절하세요.', lv3: '(E)\'쌍검협무\'로 아이번을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입하여 딜교환을 해요. 아이번의 (E)\'보호의 씨앗\'이 터지며 둔화가 걸리기 전에 공격을 몰아넣으세요.', lv6: '(R)\'선봉진격검\'으로 표식을 남기고 (Q)\'칼날 쇄도\'로 진입해 빠르게 처치하세요. (R)\'데이지!\'가 소환되어 연속 공격 후 공중으로 띄울 수 있으니 주의하며 라인을 관리해요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가요. 몰락한 왕의 검은 공격 속도와 생명력 흡수를 제공하며 헤르메스의 발걸음은 마법 저항력과 강인함으로 기절과 속박 지속 시간을 줄여줘요.', spell: '점멸과 점화예요. 점멸로 (Q)\'덩굴뿌리\'를 피하며 진입하고 점화로 마무리 피해를 입혀 적을 처치하세요.' },
    '아지르': { lv1: '1~2레벨에는 (W)\'일어나라!\'의 견제를 버티며 미니언을 통해 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. (Q)\'사막의 맹습\'의 둔화에 걸리지 않게 주의하며 (Q)\'칼날 쇄도\'로 빠르게 미니언을 정리해 체력을 회복해요.', lv3: '(E)\'쌍검협무\'로 아지르를 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 피해를 입히세요. 아지르가 (E)\'신기루\'로 모래 병사에게 질주해 거리를 벌리기 전에 공격을 마치는 것이 중요해요. 진입하며 받는 피해는 (W)\'저항의 춤\'으로 적절히 감소시키세요.', lv6: '(R)\'선봉진격검\'을 적중시켜 표식을 남긴 후 (Q)\'칼날 쇄도\'로 진입해 킬각을 보세요. 아지르가 (R)\'황제의 진영\'으로 밀어내어 거리를 벌리려 할 때 당황하지 말고 다시 진입 경로를 찾으세요. 라인을 당겨 정글러와 함께 아지르를 압박해요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 마법 저항력과 강인함으로 견제를 버티고 생명력 흡수로 유지력을 높여요.', spell: '점멸과 점화를 선택하세요. 부족한 진입 거리를 보완하고 교전 시 강력한 마무리 피해를 입히기 위해서예요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸고 (P)\'암살자의 표식\' 원을 이용해 평타 사거리를 늘리려 해요. (Q)\'칼날 쇄도\'로 미니언을 타며 거리 조절을 하고 아칼리가 평타를 치러 들어오는 타이밍에 맞춰 공격하세요. 무리하게 딜교환하기보다 미니언 체력을 깎아 진입 각을 만드는 것이 좋아요.', lv3: '(E)\'쌍검협무\'를 맞히면 아칼리가 불안정 상태가 되니 (Q)\'칼날 쇄도\'로 빠르게 접근해 공격하세요. 아칼리가 (W)\'황혼의 장막\' 안에 있으면 (Q)\'칼날 쇄도\'는 대상으로 지정할 수 없지만 (E)\'쌍검협무\'는 범위 스킬이라 그대로 맞으니, 연막이 걷히면 진입하세요. (E)\'표창곡예\'의 돌진에 맞을 때는 (W)\'저항의 춤\'으로 마법 피해를 줄이며 버티세요.', lv6: '(R)\'선봉진격검\'을 맞히면 표식이 남으므로 (Q)\'칼날 쇄도\'로 진입해 빠르게 몰아붙이세요. 아칼리가 (R)\'무결처형\'으로 도약해 도망가려 하면 결계의 둔화를 이용해 끝까지 추격하세요. 아칼리가 연막 속에 숨어 (R)\'무결처형\'의 두 번째 돌진을 준비한다면 거리 조절에 신경 써야 해요.', item: '몰락한 왕의 검으로 지속 피해와 공격 속도를 챙겨 지속 교전 능력을 높이세요. 신발은 아칼리의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎아 마무리 피해를 주고 킬각을 잡으세요.' },
    '아크샨': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'이 날아가고 돌아오며 여러 번 맞을 수 있으니 직선 경로에서 벗어나 체력을 보존하세요. (Q)\'칼날 쇄도\'로 미니언을 처치하며 (P)\'아이오니아의 열정\' 중첩을 쌓고 기회를 기다리세요.', lv3: '(E)\'쌍검협무\'를 맞춰 기절시킨 후 (Q)\'칼날 쇄도\'로 빠르게 접근해 딜교환을 하세요. 상대가 (E)\'영웅의 비상\'으로 도망치기 전에 빠르게 스킬을 쏟아붓는 것이 중요해요. (W)\'저항의 춤\'으로 상대의 순간적인 물리 피해를 줄이며 버티세요.', lv6: '(R)\'선봉진격검\'으로 상대를 둔화시키고 표식을 남겨 (Q)\'칼날 쇄도\' 진입 각을 잡으세요. 하지만 체력이 낮을 때 (R)\'인과응보\'에 맞으면 바로 처치될 수 있으니 주의해야 해요. 라인을 밀어 넣어 상대가 (E)\'영웅의 비상\'을 쓰기 어려운 구도를 만드세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 몰락한 왕의 검은 추격 능력과 생명력 흡수를 제공해요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 빠른 라인 복귀와 합류를 챙기고, 점멸로 (E)\'쌍검협무\' 적중 각을 보완하세요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중으로 띄워지니 거리 조절을 하며 범위를 피하세요. (P)\'사신 태세\'가 활성화된 평타에는 체력 회복이 붙으니 정면 대결은 피하고 (Q)\'칼날 쇄도\'로 미니언을 타며 스택을 쌓으세요. 1~2레벨에는 무리한 딜교환보다는 경험치 수급에 집중하세요.', lv3: '(E)\'쌍검협무\'를 맞혀 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입하여 딜교환을 시도하세요. 아트록스의 (W)\'지옥사슬\'에 맞으면 장판 중앙으로 끌려가 다시 피해를 입으니 곧바로 범위 밖으로 벗어나세요. (W)\'저항의 춤\'으로 (Q)\'다르킨의 검\'의 물리 피해를 감소시키며 버티는 것이 중요해요.', lv6: '(R)\'선봉진격검\'을 적중시켜 표식을 남기면 (Q)\'칼날 쇄도\'를 연속으로 사용하여 빠르게 체력을 깎을 수 있어요. 아트록스가 (R)\'세계의 종결자\'를 사용하면 회복량이 늘어나니 정면 승부보다는 스킬 쿨타임을 기다리세요. 라인 관리 중 정글러가 오면 (E)\'쌍검협무\'로 적을 묶어 확실하게 처리하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 아트록스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 아트록스는 (E)\'파멸의 돌진\'과 (R)\'세계의 종결자\'로 회복량이 많으므로 점화의 치유 감소가 꼭 필요해요.' },
    '암베사': { lv1: '1~2레벨에는 미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 먼저 쌓는 것이 중요해요. 암베사가 (P)\'용사냥개의 발걸음\'으로 돌진하며 강화 평타를 치려 할 때 거리를 조절하며 미니언을 타고 움직이세요. 암베사의 (Q)\'교활한 휩쓸기\' 날 부분에 맞지 않도록 위치를 잘 잡아야 해요.', lv3: '(E)\'쌍검협무\'를 적중시켜 암베사를 기절시키고 (Q)\'칼날 쇄도\'로 진입하여 딜교환을 시작하세요. 암베사가 (W)\'배척\'을 사용하며 보호막을 얻을 때는 공격을 잠시 멈춰 피해량이 늘어나는 것을 방지하세요. 암베사의 (E)\'찢어 가르기\' 둔화가 적용되기 전에 (W)\'저항의 춤\'을 사용하여 피해를 줄이며 싸우는 것이 좋아요.', lv6: '(R)\'선봉진격검\'을 사용하여 적들에게 표식을 남기고 (Q)\'칼날 쇄도\'로 빠르게 진입해 몰아붙이세요. 암베사의 (R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적 챔피언에게 순간 이동해 제압하니, 체력이 낮을 때는 사거리 안에서 혼자 멀리 떨어져 있지 마세요. 암베사가 궁극기로 진입하기 전에 라인을 관리하여 정글러의 지원을 받기 쉬운 환경을 만드세요.', item: '몰락한 왕의 검을 첫 코어로 가서 생명력 흡수와 공격력을 챙기세요. 신발은 암베사의 물리 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 암베사의 체력이 낮아졌을 때 점화로 마무리하여 탈출을 방지하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 기절을 노리며 견제해요. 미니언을 (Q)\'칼날 쇄도\'로 이용해 이동하며 최대한 스킬을 피하면서 거리를 좁히세요. 초반에는 미니언을 활용해 (P)\'아이오니아의 열정\' 중첩을 쌓는 것에 집중하세요.', lv3: '애니비아가 (Q)\'냉기 폭발\'을 사용해 기절을 시도할 때 옆으로 움직여 피하는 것이 중요해요. (Q)\'냉기 폭발\'을 피했다면 (Q)\'칼날 쇄도\'로 빠르게 접근하여 (E)\'쌍검협무\'로 기절을 시키고 딜교환을 하세요. (E)\'동상\'은 냉각 상태인 적에게 피해가 늘어나니 구체를 맞은 직후에는 거리를 두세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 펼치면 둔화와 피해가 들어오니 장판 안에서 무리하게 싸우지 마세요. 애니비아는 치명적인 피해를 입으면 (P)\'환생\'으로 부활하니 (R)\'선봉진격검\'으로 표식을 남긴 뒤 확실하게 마무리해야 해요. (W)\'결정화\' 벽에 막혀 접근이 차단되지 않도록 주의하며 정글러와 함께 압박하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 애니비아의 마법 피해와 기절 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 애니비아는 (P)\'환생\'으로 한 번 더 살아나니 환생 이후에도 마무리할 수 있게 점화의 지속 고정 피해를 챙기세요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'으로 견제할 때 미니언을 이용해 (Q)\'칼날 쇄도\'로 빠르게 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. (P)\'낭인의 길\' 보호막이 있을 때는 정면 충돌을 피하고 평타로 보호막을 먼저 걷어낸 뒤 진입하세요. 회오리바람에 띄워지지 않게 거리 조절을 하며 초반 웨이브를 받아내세요.', lv3: '(W)\'바람 장막\'은 모든 투사체를 막으니, 장막이 깔린 방향으로는 스킬을 아끼고 장막이 빠진 뒤에 (E)\'쌍검협무\'를 맞히세요. (E)\'쌍검협무\'로 기절시킨 후 (Q)\'칼날 쇄도\'로 진입해 공격하면 피해를 많이 입힐 수 있어요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 빠르게 접근하면 (W)\'저항의 춤\'으로 물리 피해를 줄이며 받아치세요.', lv6: '(R)\'선봉진격검\' 역시 투사체라 (W)\'바람 장막\'에 막히니 반드시 벽이 사라진 후에 사용해 표식을 남기세요. (Q)\'강철 폭풍\'의 회오리에 맞아 공중에 뜨면 (R)\'최후의 숨결\'로 이어지니 중첩이 쌓인 야스오와는 거리를 유지하세요. 야스오가 띄우기 연계를 노릴 때는 라인을 당겨 맞교환을 피하세요.', item: '몰락한 왕의 검을 초반 코어로 선택해 공격 속도와 생명력 흡수 능력을 갖추세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 야스오는 돌진기가 많아 붙고 빠지니 점화의 지속 고정 피해로 마무리 각을 보완하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 견제하고 (P)\'바위 피부\'로 싸울수록 방어력이 높아져요. 1~2레벨에는 (Q)\'칼날 쇄도\'로 미니언을 타며 짧게 딜교환하고 빠르게 빠지세요. 무리하게 붙어 있다가 오공의 (Q)\'파쇄격\'에 방어력을 깎이면 피해가 크게 들어오니 주의하세요.', lv3: '오공이 (E)\'근두운 급습\'으로 진입하면 (E)\'쌍검협무\'를 정확히 맞혀 기절시키고 (Q)\'칼날 쇄도\'로 추격하세요. (W)\'분신 전사\'로 투명해지면 억지로 쫓지 말고 분신과 본체의 위치를 확인하세요. 오공의 돌진기가 빠진 시점이 (E)\'쌍검협무\'로 표식을 남기고 공격하기 가장 좋은 때예요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 정면 돌진보다는 (R)\'선봉진격검\'으로 먼저 표식을 남기고 진입하세요. 오공이 (R)\'회전격\'을 사용해 휘두르는 동안은 거리를 유지하며 (Q)\'칼날 쇄도\' 재사용 대기시간을 기다리세요. (R)\'회전격\'이 끝난 직후가 가장 취약한 상태이므로 (E)\'쌍검협무\'와 함께 몰아쳐서 킬각을 잡으세요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 몰락한 왕의 검으로 체력 비례 피해를 입히고 판금 장화로 오공의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 오공은 (P)\'바위 피부\'로 인해 전투가 길어지면 단단해지니 점화로 빠르게 체력을 깎아 마무리하세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 던지고 다시 불러들이며 견제하니, 투사체가 되돌아오는 경로를 옆으로 피하세요. (Q)\'칼날 쇄도\'로 미니언을 타며 무리하게 진입하기보다, 상대의 스킬이 빠진 틈을 타서 짧게 딜교환을 하세요. 초반에는 미니언 뒤에서 체력을 보존하며 기회를 기다리세요.', lv3: '(E)\'마법의 문\'은 둔화를 걸고 뒤로 물러나니, 이 스킬이 빠진 직후에 (E)\'쌍검협무\'를 맞춰 기절시키세요. (W)\'장막 너머로\'로 투명해진 오로라를 억지로 쫓지 말고, 투명이 풀리는 시점에 맞춰 (Q)\'칼날 쇄도\'로 진입해 공격 속도를 높이세요. 상대의 (Q)\'이중 저주\'를 피하며 기절을 맞히는 것이 중요해요.', lv6: '오로라의 (R)\'세계의 경계\'는 적중한 적을 둔화시키는 영역을 만들고 오로라가 영역을 넘나들 수 있으니 영역 안에서 오래 싸우지 마세요. (R)\'선봉진격검\'을 맞혀 표식을 남긴 뒤 (E)\'마법의 문\'으로 거리를 벌리려는 오로라를 (Q)\'칼날 쇄도\'로 추격해 킬각을 잡으세요. 정글러가 올 때는 영역에서 둔화되지 않도록 위치를 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 강력한 공격력과 생명력 흡수로 맞서세요. 신발은 오로라의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '오른': { lv1: '(Q)\'칼날 쇄도\'로 미니언을 타고 이동하며 (P)\'아이오니아의 열정\' 스택을 빠르게 쌓는 것이 중요해요. 오른의 (Q)\'용암 균열\'은 균열 경로에 피해와 둔화를 주니 옆으로 피하고, 생긴 용암 기둥 근처에서는 (E)\'화염 돌진\'에 띄워질 수 있으니 멀리 서세요. 미니언을 활용해 (Q)\'칼날 쇄도\'의 재사용 대기시간을 관리하며 거리를 조절하세요.', lv3: '(E)\'쌍검협무\'를 적중시켜 기절시킨 후 (Q)\'칼날 쇄도\'로 진입하여 딜교환을 시작하세요. 오른의 (W)\'불꽃 풀무질\' 마지막 불꽃에 맞으면 불안정 상태가 되어 이동 불가 효과의 지속시간이 길어지니 주의해야 해요. (E)\'화염 돌진\'이 벽에 부딪혀 공중으로 띄우는 것을 피하기 위해 벽 근처에서는 조심하세요.', lv6: '(R)\'선봉진격검\'으로 적을 불안정 상태로 만들어 (Q)\'칼날 쇄도\'를 더 효과적으로 활용하세요. 오른의 (R)\'대장장이 신의 부름\' 정령이 지나가는 길목에 서지 말고 정령의 진행 방향을 잘 살피세요. 정령에 부딪혀 공중으로 띄워지면 스킬을 쓸 수 없으니 정령의 위치에 따라 움직임을 조절하며 라인을 관리하세요.', item: '오른의 높은 체력을 깎기 위해 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화는 오른에게 추가 고정 피해를 입혀 킬각을 잡는 데 도움을 줘요.' },
    '올라프': { lv1: '미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 먼저 쌓으며 파밍하세요. 올라프가 (Q)\'역류\'를 던져 방어력을 깎고 도끼를 주우러 오는 동안에는 거리를 벌리며 대응해야 해요. 1~2레벨에는 올라프의 평타 교환이 강하니 무리하게 들이받지 마세요.', lv3: '(W)\'버티기\'로 보호막을 얻은 올라프에게 (Q)\'칼날 쇄도\'로 무작정 진입하는 것은 좋지 않아요. (E)\'쌍검협무\'를 맞춰 기절시킨 뒤에 공격을 이어가며 (P)\'아이오니아의 열정\' 중첩을 활용하세요. 올라프의 (Q)\'역류\'가 빠진 타이밍을 노려 짧고 강력하게 딜교환을 시도하세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 (E)\'쌍검협무\'로 기절을 시킬 수 없으니 정면 대결을 피하세요. (R)\'선봉진격검\'으로 표식을 남기고 올라프의 궁극기가 끝날 때까지 거리를 조절하며 버티는 것이 중요해요. 체력이 낮은 올라프가 (P)\'광전사의 분노\'로 흡혈을 늘리기 전에 정글러와 함께 대응하세요.', item: '몰락한 왕의 검과 판금 장화를 가세요. 몰락한 왕의 검은 공격력과 생명력 흡수를 제공하고 판금 장화는 올라프의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 체력이 낮은 올라프를 확실하게 처치하기 위해 점화가 필요해요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\'을 두 번 적중시킨 뒤 돌진하며 띄우는 공격을 주의하세요. (Q)\'칼날 쇄도\'로 미니언을 타며 빠르게 움직여 요네의 돌풍 공격 경로에서 벗어나세요. (P)\'사냥꾼의 길\' 때문에 두 번째 평타 피해가 크니 짧게 딜교환하고 빠지세요.', lv3: '요네가 (E)\'영혼해방\'으로 들어오면 (E)\'쌍검협무\'를 던져 기절시키고 표식을 남기세요. (W)\'영혼 가르기\'로 보호막을 얻었을 때는 (W)\'저항의 춤\'으로 물리 피해를 줄이며 버티는 것이 좋아요. 요네가 다시 육신으로 돌아가는 타이밍에 맞춰 (Q)\'칼날 쇄도\'로 추격해 피해를 입히세요.', lv6: '요네의 (R)\'운명봉인\'은 경로의 마지막 챔피언 뒤로 이동하며 적을 끌어당겨 띄우니 직선 경로에서 벗어나 맞지 않게 주의하세요. (R)\'선봉진격검\'을 적중시켜 요네를 둔화시키고 (Q)\'칼날 쇄도\'를 연계해 빠르게 진입하세요. 요네가 (E)\'영혼해방\'을 쓴 상태에서 (R)\'운명봉인\'을 사용하면 도망치기 어려우니 거리 조절에 신경 쓰세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수로 지속 싸움 능력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네의 (W)\'영혼 가르기\' 보호막 이후 빠르게 체력을 깎아 마무리하기 좋아요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 치며 무덤을 쌓고 안개 망령을 불러내요. (P)\'아이오니아의 열정\' 중첩을 쌓기 위해 미니언을 (Q)\'칼날 쇄도\'로 빠르게 정리하며 거리 조절을 하세요. 초반에는 요릭의 평타 추가 피해가 강하니 무리하게 붙지 말고 짧은 딜교환만 반복하세요.', lv3: '요릭의 (E)\'애도의 안개\'를 맞으면 둔화되고 망령이 몰려오니 구체를 피하는 것이 가장 중요해요. (W)\'망자의 진\' 벽에 막혔을 때는 당황하지 말고 벽을 평타로 부수거나 돌아서 접근하세요. (E)\'쌍검협무\'로 요릭을 기절시킨 뒤 중첩을 활용해 빠르게 공격하고 빠지세요.', lv6: '(R)\'군도의 장송곡\'으로 안개 마녀가 소환되면 지속 싸움이 힘들어지니 빠르게 승부를 보세요. (R)\'선봉진격검\'을 요릭에게 맞혀 표식을 남기고 (Q)\'칼날 쇄도\'로 빠르게 진입하세요. 안개 마녀가 라인을 밀 때 무리하게 막기보다 (W)\'저항의 춤\'으로 피해를 줄이며 천천히 밀어내세요.', item: '몰락한 왕의 검을 가서 체력 비례 피해와 공격 속도를 챙기세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'최후의 의식\'의 체력 회복을 점화로 억제해야 빠르게 처치할 수 있어요.' },
    '우디르': { lv1: '우디르는 (P)\'가교\' 효과로 초반 평타 속도가 빠르고 (Q)\'야생 발톱\'의 추가 피해가 강력해요. (E)\'불길 쇄도\'를 켜고 다가올 때 기절을 맞지 않도록 거리를 유지하세요. 미니언에 (Q)\'칼날 쇄도\'를 사용해 빠르게 중첩을 쌓고 짧게 딜교환하세요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻고 체력을 회복하니 보호막이 사라질 때까지 기다리세요. (E)\'쌍검협무\'를 먼저 맞춰 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 공격하세요. (E)\'불길 쇄도\'의 기절이 빠진 것을 확인하고 들어가야 일방적으로 공격할 수 있어요.', lv6: '(R)\'날개 돋친 폭풍\'의 둔화가 심하므로 (R)\'선봉진격검\'을 맞춰 적을 불안정 상태로 만든 뒤 빠르게 진입하세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 된 상태라면 (E)\'쌍검협무\'를 써도 기절하지 않으니 주의하세요. 정글 개입 시에는 (Q)\'칼날 쇄도\'의 기동력을 이용해 빠르게 합류하세요.', item: '몰락한 왕의 검과 판금 장화를 가세요. 몰락한 왕의 검으로 체력이 높은 우디르에게 피해를 입히고, 판금 장화로 (Q)\'야생 발톱\'을 포함한 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (W)\'강철 갑옷\'의 체력 회복 효과를 점화로 억제해 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 견제하고 평타에 (P)\'화염의 메아리\' 피해가 섞여 초반 체력 관리가 중요해요. (Q)\'부식성 폭약\'이 떨어지는 위치를 빠르게 피하며 (Q)\'칼날 쇄도\'로 미니언을 정리하고 체력을 회복하세요. 무리하게 붙기보다는 짧게 교환하며 상대의 체력을 갉아먹으세요.', lv3: '우르곳의 (E)\'경멸\'에 맞으면 기절하며 우르곳 뒤로 던져지니 상대의 (E)\'경멸\'이 빠진 것을 확인하고 (Q)\'칼날 쇄도\'로 진입하세요. (E)\'쌍검협무\'로 기절시킨 뒤 빠르게 공격하고, 상대가 (W)\'심판의 원\'을 켜면 (W)\'저항의 춤\'으로 물리 피해를 감소시키며 버티세요. (Q)\'부식성 폭약\'에 맞으면 (W)\'심판의 원\'의 우선 공격 대상이 되니 주의하세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞으면 체력이 낮을 때 처형될 수 있으니, 섬광탄을 맞았다면 체력을 관리하며 거리를 벌리세요. (R)\'선봉진격검\'으로 적을 둔화시키고 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 피해를 넣으세요. 우르곳의 (E)\'경멸\' 돌진이 빗나간 순간이 가장 좋은 킬각이니 집중하세요.', item: '몰락한 왕의 검을 가서 체력이 많은 우르곳에게 비율 피해를 입히고 공격 속도를 챙기세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 (R)\'불사의 공포\' 처형선에 도달하기 전에 점화로 빠르게 체력을 깎아 처치하세요.' },
    '워윅': { lv1: '1~2레벨에는 워윅이 (Q)\'야수의 송곳니\'로 도약해 체력을 회복하며 압박하니 주의하세요. 미니언에 (Q)\'칼날 쇄도\'를 사용해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으며 파밍하는 것이 중요해요. 워윅의 체력이 낮아져 (P)\'끝없는 허기\' 효과가 강해지기 전에 거리를 조절하세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용해 받는 피해를 줄이는 동안에는 (Q)\'칼날 쇄도\'로 억지로 딜교하지 마세요. (E)\'쌍검협무\'를 적중시켜 불안정 상태로 만든 뒤에 (Q)\'칼날 쇄도\'로 들어가면 딜교를 더 원활하게 할 수 있어요. 워윅의 (Q)\'야수의 송곳니\'가 빠진 타이밍을 노려 (P)\'아이오니아의 열정\' 중첩을 활용해 몰아치세요.', lv6: '워윅이 (R)\'무한의 구속\'으로 제압을 걸면 점멸이나 스킬을 사용할 수 없으니 체력이 낮을 때는 주의해야 해요. (R)\'선봉진격검\'으로 적들에게 표식을 남기고 (Q)\'칼날 쇄도\'를 연계하면 한 번에 몰아칠 수 있어요. 내 체력이 낮아지면 워윅이 (W)\'피의 사냥\'으로 이동 속도가 빨라져 쫓아오니 정글러 위치를 확인하며 물러나세요.', item: '몰락한 왕의 검을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 워윅의 마법 피해와 (E)\'원시의 포효\'의 공포 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 체력 회복을 억제할 수 있어요.' },
    '일라오이': { lv1: '1~2레벨에는 미니언을 활용해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으며 싸울 준비를 하세요. 일라오이가 (Q)\'촉수 강타\'를 사용할 때 촉수 근처에 있으면 피해가 커지니 촉수가 없는 곳으로 위치를 잡으세요. 미니언을 타고 (Q)\'칼날 쇄도\'로 빠르게 움직이며 일라오이의 공격 범위를 벗어나세요.', lv3: '일라오이가 (E)\'영혼의 시험\'을 사용하면 영혼과 너무 멀어지지 않게 위치를 조절하여 숙주가 되는 것을 방지하세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약해 들어올 때 (E)\'쌍검협무\'를 맞춰 기절시키며 대응하세요. (W)\'저항의 춤\'을 사용하여 일라오이가 입히는 물리 피해를 줄이며 딜교환을 하세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하여 촉수를 많이 소환했다면 근처에서 싸우지 말고 빠르게 거리를 두세요. (R)\'믿음의 도약\' 사용 직후에는 촉수가 늘어나니 라인을 당겨서 받아내며 정글의 도움을 기다리세요. 영혼이 뽑힌 상태에서 (R)\'선봉진격검\'을 사용해 표식을 남기고 빠르게 승부를 보세요.', item: '몰락한 왕의 검을 첫 코어로 올려 공격 속도와 생명력 흡수를 챙기세요. 신발은 일라오이의 물리 피해를 줄이기 위해 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 체력이 낮아진 일라오이를 확실하게 처치하세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 적을 붙잡아 둔화시키고 조각을 회복해요. (Q)\'칼날 쇄도\'로 미니언을 타며 거리를 조절하고, 자크가 팔을 뻗는 경로에서 벗어나세요. 자크가 조각을 줍기 위해 움직일 때 평타로 압박하며 체력을 깎아내세요.', lv3: '자크가 (E)\'새총 발사\'로 날아올 때 방향을 틀어 피하고, 착지 직후 (E)\'쌍검협무\'를 맞춰 기절시키세요. 자크가 붙어서 (W)\'불안정 물질\'로 최대 체력 비례 피해를 주려 하면 (W)\'저항의 춤\'으로 피해를 줄이며 맞받으세요. 스킬을 모두 뺀 자크를 상대로 (Q)\'칼날 쇄도\' 초기화를 활용해 빠르게 공격하세요.', lv6: '자크의 (R)\'바운스!\'에 맞으면 뒤로 밀리며 둔화되니 착지 지점에서 거리를 벌리며 주의하세요. (R)\'선봉진격검\'으로 자크에게 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 피해를 누적하세요. 자크가 (P)\'세포 분열\'로 갈라져 부활하려 하면 조각들을 빠르게 제거해 부활을 막으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 자크에게 지속 피해를 입히세요. 신발은 (W)\'불안정 물질\' 같은 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'세포 분열\'을 통한 자크의 체력 회복을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하고 (P)\'전쟁 단련\' 중첩을 쌓아 강해져요. 1~2레벨에는 무리하게 붙지 말고 미니언을 이용해 (Q)\'칼날 쇄도\'로 짧게 딜교환을 하세요. 자헨이 공격적으로 나오면 뒤로 물러나며 거리 조절을 하는 것이 중요해요.', lv3: '(W)\'공포의 귀환\'에 끌려가면 위험하니 직선 경로에서 빠르게 벗어나세요. (E)\'쌍검협무\'로 자헨을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 빠르게 공격하세요. 자헨이 (E)\'찬란한 쇄도\'로 진입할 때 (W)\'저항의 춤\'으로 물리 피해를 줄이며 버티는 것이 좋아요.', lv6: '(R)\'단호한 판결\'이 내려찍는 지점에서 빠르게 벗어나 체력 회복을 방해하세요. (R)\'선봉진격검\'을 맞혀 둔화를 걸고 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 추격해 처치하세요. (P)\'전쟁 단련\' 효과로 부활할 수 있으니 적의 체력이 낮아져도 끝까지 방심하지 마세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수로 유지력을 높이세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'의 체력 회복을 점화의 치유 감소로 억제해야 해요.' },
    '잭스': { lv1: '1~2레벨에는 잭스가 (Q)\'도약 공격\'으로 들어오며 (W)\'무기 강화\'를 섞은 평타를 치기 때문에 거리를 조절해야 해요. 미니언에 (Q)\'칼날 쇄도\'를 사용해 스택을 쌓으며 체력을 관리하고 잭스의 공격이 시작되기 전에 움직이세요. 잭스가 미니언을 치러 올 때 짧게 딜교환을 하고 빠지는 것이 좋아요.', lv3: '3레벨 이후에는 잭스의 (E)\'반격\'을 어떻게 대응하느냐가 중요해요. 잭스가 (E)\'반격\'을 사용해 평타를 피하려고 하면 (Q)\'칼날 쇄도\'로 무리하게 진입하지 말고 스킬을 아끼세요. (E)\'쌍검협무\'를 먼저 맞춰서 잭스를 불안정 상태로 만든 뒤에 딜교환을 시작하는 것이 효율적이에요.', lv6: '6레벨 이후에는 잭스가 (R)\'무기의 달인\'을 사용하여 방어력과 마법 저항력을 높이므로 정면 대결을 주의하세요. 잭스의 (E)\'반격\'이 끝난 직후 (R)\'선봉진격검\'으로 광역 피해를 입히고 (Q)\'칼날 쇄도\'를 연계해 킬각을 잡으세요. 잭스가 (Q)\'도약 공격\'으로 도망치지 못하도록 미니언을 활용해 진입 타이밍을 잡는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 잭스의 체력을 깎아 마무리 피해를 더하고 킬을 따기 쉽게 만드세요.' },
    '제이스': { lv1: '제이스는 캐논 형태의 (Q)\'전격 폭발\'로 멀리서 견제하니 구체의 직선 경로에서 벗어나세요. 미니언에 (Q)\'칼날 쇄도\'를 사용해 체력을 회복하며 버티고, 제이스가 막타를 위해 다가오면 평타로 압박하세요. 초반에는 무리하게 붙기보다 미니언을 활용해 거리를 조절하는 것이 중요해요.', lv3: '(E)\'쌍검협무\'를 맞혀 제이스를 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 접근해 공격하세요. 제이스가 해머 형태의 (E)\'천둥 강타\'로 밀쳐내려 하면 (W)\'저항의 춤\'으로 마법 피해를 줄이며 버티세요. (E)\'가속 관문\'을 통한 (Q)\'전격 폭발\'은 피해가 크니 관문이 열리면 즉시 옆으로 움직여 피하세요.', lv6: '(R)\'선봉진격검\'을 맞혀 제이스에게 표식을 남기고 둔화를 걸면 추격하기 편해져요. 제이스가 (R)\'머큐리 캐논\'으로 변환해 방어력을 깎으려 하면 바로 (Q)\'칼날 쇄도\'로 진입해 딜교환을 끝내세요. (R)\'머큐리 해머\'로 변환해 단단해진 순간에는 무리하게 붙지 말고 라인을 관리하며 정글의 도움을 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 가서 빠른 공격 속도와 생명력 흡수로 지속 전투력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (E)\'쌍검협무\' 이후 점화로 체력을 깎아 빠르게 킬각을 잡으세요.' },
    '초가스': { lv1: '초가스의 (Q)\'파열\'은 바닥에 표시가 나타나니 옆으로 움직여 범위를 빠르게 벗어나세요. (E)\'날카로운 가시\'가 평타마다 전방에 피해와 둔화를 주니 정면에서 오래 싸우지 마세요. 미니언을 (Q)\'칼날 쇄도\'로 처치하며 중첩을 쌓고 짧게 딜교환하세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 스킬을 쓸 수 없으니, 침묵 범위 밖에서 대기하다가 스킬이 빠진 뒤에 진입하세요. (E)\'쌍검협무\'로 기절시킨 뒤 (Q)\'칼날 쇄도\'로 파고들어 공격하세요. (Q)\'파열\'의 원형 표시를 피하는 것이 딜교환의 핵심이에요.', lv6: '(R)\'선봉진격검\'으로 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하세요. 체력이 낮을 때 (R)\'포식\'에 맞으면 큰 고정 피해로 처치될 수 있으니 항상 주의하세요. (Q)\'파열\'을 빗맞힌 순간이 가장 좋은 기회이니 그때 모든 스킬을 쏟아부으세요.', item: '체력이 많은 초가스를 잡기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 초가스의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'을 통한 체력 회복을 방해하세요.' },
    '카밀': { lv1: '1~2레벨에는 미니언을 (Q)\'칼날 쇄도\'로 타고 다니며 (P)\'아이오니아의 열정\' 중첩을 쌓는 것이 중요해요. 카밀의 (P)\'적응형 방어 체계\' 보호막이 있을 때는 (Q)\'칼날 쇄도\'로 무리하게 진입하지 말고 스택을 먼저 만드세요. (Q)\'정확성 프로토콜\' 강화 평타를 맞지 않도록 거리를 조절하며 미니언 막타를 챙기세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽 절반에 맞으면 둔화되고 카밀이 체력을 회복하니 원뿔 안쪽으로 붙거나 피해야 해요. 카밀의 (E)\'갈고리 발사\'로 들어올 때 (E)\'쌍검협무\'를 적중시켜 기절을 맞히면 딜교환을 편하게 할 수 있어요. (W)\'저항의 춤\'을 사용해서 카밀의 물리 피해를 줄이며 안정적으로 싸우세요.', lv6: '카밀의 (R)\'마법공학 최후통첩\'에 걸리면 지정 지역 안에 갇혀 탈출할 수 없으니 체력이 낮을 때는 거리를 유지하세요. (R)\'선봉진격검\'을 사용하여 카밀과 주변 적들에게 표식을 남기고 전투를 이끌어가세요. 카밀이 (E)\'갈고리 발사\'를 활용해 정글러와 함께 들어올 수 있으니 라인 관리에 주의를 기울여야 해요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀의 (W)\'전술적 휩쓸기\' 회복을 억제하고 킬각을 잡기에 좋아요.' },
    '카사딘': { lv1: '(Q)\'무의 구체\'는 대상 지정 스킬이라 피할 수 없으니 1~2레벨에는 맞는 만큼 체력을 관리하며 미니언을 통해 패시브 중첩을 쌓으세요. (Q)\'칼날 쇄도\'로 미니언을 타며 빠르게 진입했다가 상대의 공격을 최소화하며 빠져나오는 식으로 딜교환을 하세요. 초반에 무리하게 진입하기보다 체력 관리를 하며 기회를 엿보세요.', lv3: '(E)\'쌍검협무\'를 맞춰 기절시킨 후 (Q)\'칼날 쇄도\'로 진입해 빠르게 공격을 퍼부으세요. 상대가 (E)\'힘의 파동\'을 사용하여 둔화를 걸려고 하면 (W)\'저항의 춤\'으로 마법 피해를 줄이며 버티는 것이 좋아요. (E)\'힘의 파동\'이 빠진 타이밍에 진입하면 상대를 강하게 압박할 수 있어요.', lv6: '(R)\'선봉진격검\'을 적중시켜 둔화시키고 표식을 남겨 (Q)\'칼날 쇄도\'로 끝까지 추격하세요. 상대가 (R)\'균열 이동\'으로 거리를 벌리더라도 결계 안에서 계속 압박하며 킬각을 잡으세요. 정글러가 올 때 (E)\'쌍검협무\'로 기절시켜 도망가지 못하게 하는 것이 중요해요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 추천해요. 몰락한 왕의 검으로 공격 속도와 생명력 흡수를 챙기고, 헤르메스의 발걸음의 마법 저항력으로 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 점멸을 사용해 (E)\'쌍검협무\'의 적중률을 높이고 순간이동으로 라인 복귀와 운영을 챙기세요.' },
    '카시오페아': { lv1: '(Q)\'칼날 쇄도\'로 미니언을 빠르게 처치하며 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. 카시오페아가 (Q)\'맹독 폭발\'을 사용해 견제하려 할 때 옆으로 움직여 피해를 피하며 경험치를 챙기세요. 무리하게 진입하기보다 체력을 보존하며 기회를 기다리는 것이 좋아요.', lv3: '(W)\'독기의 늪\'이 깔린 지역에서는 (Q)\'칼날 쇄도\'를 쓸 수 없으니 늪 밖에서 딜교환을 하세요. (E)\'쌍검협무\'를 먼저 적중시켜 기절시킨 뒤 빠르게 진입해 공격을 퍼부으세요. 상대의 (E)\'쌍독니\' 견제를 버티며 패시브 중첩을 유지하는 것이 중요해요.', lv6: '(R)\'선봉진격검\'을 맞혀 표식을 남긴 뒤 빠르게 진입해 킬각을 보세요. 카시오페아가 (R)\'석화의 응시\'를 사용하면 즉시 몸을 돌려 기절을 피하고 둔화만 맞으세요. 라인을 밀어넣고 정글러와 함께 (W)\'독기의 늪\' 범위 밖에서 협공하세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가세요. 헤르메스의 발걸음의 마법 저항력과 강인함이 필요하며 몰락한 왕의 검으로 공격 속도와 생명력 흡수를 챙기세요.', spell: '점멸과 점화. (E)\'쌍독니\'의 체력 회복 효과를 줄이고 부족한 킬 결정력을 높이기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 날려 (P)\'폭풍의 표식\'을 쌓으며 견제해요. 미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으세요. 표식이 쌓이기 전에 거리를 조절하며 미니언을 놓치지 않는 것이 중요해요.', lv3: '(E)\'쌍검협무\'로 케넨을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입하여 딜교환을 시도하세요. 케넨이 (E)\'번개 질주\'로 도망가려 하면 (E)\'쌍검협무\'의 표식을 이용해 추격하세요. 케넨의 (W)\'전류 방출\'이 빠진 타이밍에 싸워야 기절을 피하기 쉬워요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력이 상승하니 주의하세요. (R)\'선봉진격검\'으로 케넨에게 표식을 남기고 (Q)\'칼날 쇄도\'를 연속해서 사용하여 압박하세요. 케넨의 궁극기가 끝난 시점에 정글러와 함께 교전하면 좋아요.', item: '첫 코어로 몰락한 왕의 검을 구매하여 전투를 지속하세요. 신발은 케넨의 마법 피해를 줄이고 기절 지속시간을 줄이는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 점멸로 케넨의 공격을 피하고 점화로 마무리 피해를 입혀 킬을 노리세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\' 효과가 낮은 초반에 매우 약하니 적극적으로 압박하세요. (Q)\'광휘의 일격\'의 경로를 피해 (Q)\'칼날 쇄도\'로 빠르게 접근해 평타를 섞어주세요. 첫 웨이브부터 강하게 밀어붙여 케일이 편하게 성장하지 못하게 하세요.', lv3: '(E)\'쌍검협무\'로 케일을 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 폭발적인 피해를 입히세요. (W)\'천상의 축복\'으로 체력을 회복하며 도망가는 케일을 쫓기보다, (E)\'화염주문검\'의 추가 피해가 들어오지 않도록 체력 관리를 하며 딜교환하세요. (Q)\'광휘의 일격\'이 빠진 타이밍이 가장 좋은 진입 기회예요.', lv6: '(R)\'선봉진격검\'으로 표식을 남기고 둔화를 걸어 케일의 도주 경로를 차단하세요. (R)\'신성한 심판\'은 대상을 무적으로 만드니, 무적 효과가 끝나는 시점에 맞춰 (Q)\'칼날 쇄도\'로 진입해 마무리하세요. 케일이 (R)\'신성한 심판\'을 쓸 때까지 스킬을 아끼며 정글러와 함께 압박하세요.', item: '몰락한 왕의 검을 가서 빠른 공격 속도와 피해를 확보하세요. 신발은 케일의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'천상의 축복\'으로 회복하는 케일의 체력 회복 효과를 점화로 줄여 확실하게 처치하세요.' },
    '코그모': { lv1: '1~2레벨에는 (Q)\'부식성 침\'의 견제가 심하므로 미니언 뒤에 숨어 피해를 최소화하세요. 무리하게 (Q)\'칼날 쇄도\'로 진입하기보다 경험치를 챙기며 기회를 기다리는 것이 좋아요.', lv3: '(E)\'쌍검협무\'로 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 접근해 공격하세요. 상대가 (E)\'공허의 분비물\'을 사용해 둔화를 걸면 접근이 어려우므로 해당 스킬이 빠진 시점을 노려야 해요.', lv6: '(R)\'선봉진격검\'으로 표식을 남겨 거리 조절을 무너뜨리고 진입해 킬각을 잡으세요. 체력이 낮을 때 (R)\'살아있는 곡사포\'에 맞으면 피해가 커지니 주의하며 정글러와 함께 압박하세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 가세요. 마법 피해가 주를 이루는 상대라 마법 저항력이 필요하고 빠른 접근과 생명력 흡수가 중요해요.', spell: '점멸과 점화를 추천해요. 부족한 돌진 거리를 보완하고 유지력이 없는 상대를 확실하게 마무리하기 위해서예요.' },
    '코르키': { lv1: '1~2레벨에는 (Q)\'인광탄\'이 범위 스킬이라 미니언 뒤에 숨어도 맞으니 폭탄이 떨어지는 지점에서 벗어나 체력을 보존하세요. (Q)\'칼날 쇄도\'로 미니언을 타며 빠르게 진입하되 상대의 (W)\'발키리\' 이동 경로에 맞지 않도록 거리 조절을 해요.', lv3: '(E)\'쌍검협무\'를 적중시켜 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입하여 빠르게 딜교환을 시도하세요. 상대가 (E)\'개틀링 건\'을 사용해 방어력과 마법 저항력을 낮추기 전에 빠르게 공격을 마치는 것이 중요해요.', lv6: '(R)\'선봉진격검\'으로 상대를 둔화시키고 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 추격하여 킬각을 잡으세요. 상대의 (R)\'미사일 폭격\' 세 번째 공격은 매우 강력하므로 거리 조절에 유의하며 정글러와 함께 압박해요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 추천해요. 몰락한 왕의 검으로 공격 속도와 피해량을 높이고 헤르메스의 발걸음의 마법 저항력으로 (Q)\'인광탄\' 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언을 상대로 갑작스러운 진입이 필요하며 라인 복귀가 중요하기 때문이에요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 이용해 기본 공격 견제가 강하니, 표식이 묻었을 때는 거리 조절을 하며 체력을 보존하세요. 미니언을 이용해 (Q)\'칼날 쇄도\'로 빠르게 진입하며 퀸의 거리 조절을 방해하고 평타 중첩을 쌓으며 압박하세요. 무리하게 붙으려다 (E)\'공중제비\'로 밀려나면 다시 거리를 잡으며 기회를 보세요.', lv3: '(E)\'쌍검협무\'를 먼저 적중시켜 퀸을 기절시키고 불안정 상태로 만든 뒤, (Q)\'칼날 쇄도\'로 빠르게 붙어 공격하세요. 퀸이 (E)\'공중제비\'로 거리를 벌리며 도망가려 하면, 기절 지속 시간 동안 최대한 많은 중첩을 쌓는 것이 중요해요. (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 당황하지 말고 퀸의 위치를 확인하며 침착하게 대응하세요.', lv6: '(R)\'선봉진격검\'을 맞춰 퀸을 둔화시키고 표식을 남기면, (Q)\'칼날 쇄도\'로 진입해 킬각을 잡을 수 있어요. 퀸이 (R)\'후방 지원\'을 사용해 빠르게 이동하며 거리를 벌리려 하면 무리하게 쫓지 말고 라인을 먼저 미세요. (W)\'저항의 춤\'으로 퀸의 순간적인 폭딜을 감소시키며 버티면 정글러의 개입을 유도하기 편해요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수를 챙기고 퀸을 추격하세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. (E)\'쌍검협무\' 적중 후 점화로 확실하게 마무리하는 각이 나와요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 적중시키면 적을 끌어당겨요. 첫 타격에 맞았다면 중첩이 쌓이지 않게 거리를 벌리고, 미니언을 (Q)\'칼날 쇄도\'로 타며 패시브 중첩을 쌓으세요. 크산테의 딜교환 시도 때 짧게 평타를 섞어 주고 빠르게 빠지세요.', lv3: '(W)\'길을 여는 자\'는 저지 불가 상태로 돌진하며 기절시키니, 충전 동작이 보이면 즉시 옆으로 피하세요. 크산테가 (E)\'발놀림\'으로 진입할 때 (E)\'쌍검협무\'를 맞춰 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 피해를 입히세요. (W)\'저항의 춤\'은 크산테의 물리 피해가 강하게 들어오는 타이밍에 사용해 피해를 줄이세요.', lv6: '(R)\'총공세\'에 맞으면 벽 너머로 밀려나며 큰 피해를 입으니 벽 근처에 서지 마세요. (R)\'선봉진격검\'을 맞춰 표식을 남긴 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하세요. 총공세 상태의 크산테는 방어력이 낮아지니 그 시점에 화력을 집중하되, 늘어난 피해량과 흡혈량에 주의하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 크산테에게 효율적인 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 상태에서 늘어나는 크산테의 체력 회복을 억제하며 킬각을 잡기 좋아요.' },
    '클레드': { lv1: '클레드는 스칼을 타고 있을 때 피해를 대신 받으므로 (Q)\'칼날 쇄도\'로 무작정 진입하기보다 미니언을 통해 중첩을 먼저 쌓으세요. (Q)\'덫날리기\'에 붙잡히면 근거리를 유지하는 동안 끌려가며 추가 피해를 입으니 거리를 벌려야 해요. 스칼의 체력을 깎아 클레드를 내리게 만드는 것이 중요해요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해 들어오는 타이밍에 맞춰 (E)\'쌍검협무\'를 사용하여 기절시키고 흐름을 끊으세요. (W)\'버럭버럭\'의 빠른 공격이 시작되면 (W)\'저항의 춤\'으로 물리 피해를 감소시키며 버티는 것이 좋아요. 클레드가 스칼에서 내렸을 때는 챔피언에 대한 피해량이 줄어드니 이때를 노려 공격하세요.', lv6: '(R)\'돌겨어어억!!!\'은 보호막을 쓰고 빠르게 돌진해 밀어내므로 일직선상에 서 있지 말고 옆으로 피하세요. (R)\'선봉진격검\'을 맞히면 적이 둔화되고 표식이 생기니 이를 활용해 (Q)\'칼날 쇄도\'로 계속 추격하며 킬각을 잡으세요. 클레드가 스칼을 다시 타기 전에 빠르게 처치하는 것이 핵심이에요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 스칼과 클레드에게 강력한 피해를 입히세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드를 점화로 빠르게 마무리하여 스칼에 다시 타지 못하게 막으세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 체력을 회복하려 해요. (Q)\'혀 채찍\'은 처음 맞는 유닛에게 적중하므로 미니언 뒤에 서서 공격을 막아내세요. (Q)\'칼날 쇄도\'로 짧게 진입해 평타를 치되, (P)\'절대 미각\' 중첩이 쌓이지 않게 빠르게 빠져나오세요.', lv3: '(E)\'쌍검협무\'를 맞춰 기절시킨 뒤 (Q)\'칼날 쇄도\'로 진입해 피해를 입히세요. 탐 켄치가 (W)\'심연 잠수\'로 뛰어올라 띄우려 하면 빠르게 옆으로 움직여 피해야 해요. (E)\'두꺼운 피부\' 보호막이 활성화된 동안에는 딜교환을 멈추고 보호막이 사라진 뒤에 다시 공격하세요.', lv6: '(R)\'선봉진격검\'으로 표식을 남겨 둔화시킨 뒤 진입해 빠르게 공격하세요. (P)\'절대 미각\' 중첩이 세 번 쌓이면 (R)\'집어삼키기\'로 먹힐 수 있으니 항상 거리를 유지하며 조심하세요. 탐 켄치의 (W)\'심연 잠수\'가 빠진 타이밍에 정글러를 불러 함께 공격하면 킬각을 잡기 편해요.', item: '몰락한 왕의 검을 첫 코어로 가서 최대 체력이 높은 탐 켄치에게 효율적인 피해를 입히세요. 신발은 마법 저항력을 높이고 군중 제어 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복을 억제하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸기 때문에 1~2레벨에 평타를 길게 섞지 마세요. (Q)\'칼날 쇄도\'로 빠르게 체력을 회복하며 짧은 딜교환만 하고 빠지는 것이 좋아요. 트런들의 (P)\'헌납\' 때문에 미니언이 많이 죽는 곳에서는 회복량이 많으니 주의하세요.', lv3: '(E)\'얼음 기둥\'은 경로를 막고 주변 적을 둔화시키므로, 이 스킬이 빠진 뒤에 (E)\'쌍검협무\'로 기절을 맞히고 진입하세요. 트런들이 (W)\'얼음 왕국\'을 깔면 공격 속도와 이동 속도가 오르니 영역 밖에서 딜교환을 유도하세요. (E)\'쌍검협무\'로 적을 불안정 상태로 만든 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 중첩을 쌓으세요.', lv6: '(R)\'선봉진격검\'으로 트런들을 둔화시키고 표식을 남겨 (Q)\'칼날 쇄도\'로 빠르게 진입해 압박하세요. 다만 (R)\'진압\'에 맞으면 방어력을 뺏겨 순식간에 체력이 낮아질 수 있으니 주의하세요. (R)\'진압\'의 지속 시간이 끝난 뒤에 다시 진입하거나 정글러의 개입을 통해 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 트런들을 효과적으로 공격하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\' 회복력을 억제하세요.' },
    '트린다미어': { lv1: '(E)\'회전 베기\'로 진입하는 트린다미어와 정면으로 맞붙지 말고 짧은 평타 교환만 하세요. 첫 웨이브에서는 (Q)\'칼날 쇄도\'를 통해 미니언을 타며 거리 조절을 하고, 상대의 분노가 쌓이지 않게 주의하세요. 무리하게 딜교환을 하기보다 경험치만 챙기며 상황을 살피세요.', lv3: '(E)\'쌍검협무\'를 적중시켜 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입해 공격하세요. (W)\'조롱의 외침\'을 맞았을 때 등을 돌리면 둔화되니 정면을 유지하며 짧게 교환하고 빠지세요. 상대가 (E)\'회전 베기\'로 들어올 때 (W)\'저항의 춤\'으로 물리 피해를 감소시키며 버티면 효율적으로 싸울 수 있어요.', lv6: '(R)\'선봉진격검\'을 맞혀 둔화를 걸고 (E)\'쌍검협무\'와 연계해 킬각을 잡으세요. 하지만 상대가 (R)\'불사의 분노\'를 켜면 죽지 않으니, 궁극기 지속 시간이 끝날 때까지 거리 조절을 하며 기다리세요. (R)\'불사의 분노\'가 종료되는 시점에 맞춰 다시 진입해 마무리하는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 선택해 높은 공격 속도와 생명력 흡수로 지속 싸움을 준비하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트린다미어는 (Q)\'피의 갈망\'으로 체력을 회복하므로 점화의 치유 감소 효과가 매우 유용해요.' },
    '티모': { lv1: '(E)\'맹독 다트\'의 지속 피해를 조심하며 미니언에 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 쌓으세요. 티모가 (P)\'유격 전투\'를 이용해 수풀에 숨을 수 있으니 미니언 근처에서 시야를 잘 확인하며 거리 조절을 해요. 초반에는 무리한 딜교환보다는 스택을 쌓는 데 집중하세요.', lv3: '티모의 (Q)\'실명 다트\'는 대상 지정 스킬이라 걸어서 피할 수 없고 맞으면 실명되니, 실명된 동안은 평타 교환을 미루세요. (Q)\'실명 다트\'가 빠진 타이밍에 (E)\'쌍검협무\'로 기절을 시키고 (Q)\'칼날 쇄도\'로 진입하여 딜교환을 해요. 티모가 (W)\'신속한 이동\'으로 도망가려 해도 (Q)\'칼날 쇄도\'로 따라붙어 압박할 수 있어요.', lv6: '티모가 설치한 (R)\'유독성 함정\'을 밟으면 이동 속도가 느려지고 모습이 드러나니 라인 곳곳의 버섯 위치를 파악하세요. (R)\'선봉진격검\'으로 티모를 맞히면 결계로 인해 둔화가 걸리므로 (Q)\'칼날 쇄도\'를 연계해 킬을 노려보세요. 티모가 (R)\'유독성 함정\'을 깔고 뒤로 빠지면 무리하게 쫓기보다 라인을 밀어넣고 정글러를 부르세요.', item: '헤르메스의 발걸음을 신어서 티모의 마법 피해를 견디고 강인함을 확보하세요. 첫 코어 아이템으로는 몰락한 왕의 검을 선택해 생명력 흡수를 챙겨요.', spell: '점멸과 점화를 추천해요. 티모의 체력을 깎아내고 킬을 확정적으로 가져오기 위해 점화가 필요해요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 사용하여 견제하며 (P)\'필멸자의 의지\'를 쌓으려 해요. 미니언에게 (Q)\'칼날 쇄도\'를 사용하여 (P)\'아이오니아의 열정\' 중첩을 쌓으며 파밍에 집중하세요. 판테온의 강화된 스킬이 빠지기 전까지는 무리하게 딜교환을 하지 말고 거리를 조절하세요.', lv3: '판테온이 (W)\'방호의 도약\'으로 들어와 기절을 시키면 스킬을 사용할 수 없으니 주의해야 해요. 판테온이 (E)\'방패 돌격\'을 쓰는 동안은 그 방향의 피해에 면역이니, 정면에서 (Q)\'칼날 쇄도\'를 쓰지 말고 스킬이 끝나거나 옆으로 돌아간 뒤에 들어가세요. 판테온의 (W)\'방호의 도약\'이 빠진 타이밍에 (E)\'쌍검협무\'를 적중시켜 기절을 시키고 전투를 시작하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 공중으로 뛰어오르면 착지 지점을 확인하고 범위 밖으로 피하세요. 판테온의 스킬 연계가 끝난 뒤에 (R)\'선봉진격검\'을 사용하여 적에게 표식을 남기고 (Q)\'칼날 쇄도\'로 공격하세요. 판테온이 (R)\'거대 유성\'을 쓰고 사라지면 다른 라인에 개입할 수 있으니 맵을 잘 살펴야 해요.', item: '판테온의 기본 공격 피해를 줄이기 위해 판금 장화를 신으세요. 첫 코어 아이템으로는 몰락한 왕의 검을 구매하여 전투 지속력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 판테온과의 교전에서 더 강력한 피해를 입히고 킬을 노리세요.' },
    '피들스틱': { lv1: '미니언을 통해 (P)\'아이오니아의 열정\' 중첩을 빠르게 쌓으며 파밍하세요. 상대가 허수아비인 척하며 (Q)\'공포\'를 사용해 기습하는 것을 조심하며 거리를 조절해야 해요. (Q)\'칼날 쇄도\'로 미니언을 처리하며 체력을 회복하고 빠르게 성장하세요.', lv3: '(E)\'쌍검협무\'를 먼저 적중시켜 기절시킨 뒤 (Q)\'칼날 쇄도\'로 빠르게 진입하세요. 상대의 (E)\'수확\' 범위 중심에서 벗어나 침묵에 걸리지 않도록 움직여야 해요. (W)\'저항의 춤\'을 적절히 사용하여 상대의 마법 피해를 줄이며 딜교환을 마무리하세요.', lv6: '시야가 없는 곳에서 (R)\'까마귀 폭풍\'으로 진입하는 기습을 가장 조심하세요. (R)\'선봉진격검\'을 맞춰 상대를 둔화시키고 진형을 무너뜨리며 킬각을 잡아야 해요. 정글러가 올 때 (E)\'쌍검협무\'로 적의 발을 묶어 확실하게 처리하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 마법 저항력과 강인함으로 군중 제어 시간을 줄이고 공격 속도와 생명력 흡수를 챙기세요.', spell: '점멸과 점화. 순간적인 진입 거리를 확보하고 강력한 피해로 적을 빠르게 처치하기 위해 사용해요.' },
    '피오라': { lv1: '피오라가 (Q)\'찌르기\'로 급소를 노리고 돌진해 들어오면 무리하게 맞서지 말고 거리를 유지하세요. (Q)\'칼날 쇄도\'로 미니언을 처치하며 (P)\'아이오니아의 열정\' 중첩을 쌓되 짧게 교환하고 빠지세요. (P)\'치명적인 검무\'로 급소를 맞혀 회복하고 이동 속도를 얻을 틈을 주지 마세요.', lv3: '피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내니 (E)\'쌍검협무\'를 쓰기 전에 피오라의 스킬 사용 여부를 확인하세요. (W)\'응수\'를 빼도록 유도한 뒤 (Q)\'칼날 쇄도\'로 진입하여 (E)\'쌍검협무\'로 기절을 시키세요. (E)\'대가의 검술\'로 강화된 평타를 맞지 않도록 조심하세요.', lv6: '피오라가 (R)\'대결투\'를 사용해 급소를 노리면 급소 방향을 계속 바꾸며 대응하세요. (R)\'선봉진격검\'으로 적을 불안정 상태로 만들어 (Q)\'칼날 쇄도\'의 초기화를 노리며 압박하세요. 피오라가 급소를 모두 가격해 치유를 받기 전에 정글러를 호출하거나 빠르게 몰아붙이세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 생명력 흡수와 공격력을 챙기세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'로 회복하는 양을 점화로 줄이세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 장악하려 해요. 1~2레벨에는 포탑의 사거리 밖에서 대기하다가 (Q)\'칼날 쇄도\'로 미니언을 빠르게 정리하며 피해를 최소화하세요. 포탑 주변에서 오래 머물면 피해가 크니 짧은 교환만 하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 기절을 피한 직후에 (E)\'쌍검협무\'를 맞춰 표식을 남기고 진입하세요. (W)\'마법공학 초소형 로켓\'이 날아오는 방향을 예측해 피하며 딜교환을 유도하세요. 포탑을 먼저 제거해야 (Q)\'칼날 쇄도\'의 초기화를 이용해 본체까지 빠르게 접근할 수 있어요.', lv6: '(R)\'업그레이드!!!\'로 강화된 스킬이 빠진 뒤가 가장 좋은 킬각 타이밍이에요. (R)\'선봉진격검\'을 맞춰 표식을 남기고 포탑의 방해를 뚫고 들어가 빠르게 공격하세요. 정글러와 함께 진입할 때 (R)\'선봉진격검\'의 둔화 효과를 이용해 하이머딩거의 도주 경로를 차단하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수로 포탑 피해를 견디세요. 신발은 (E)\'CH-2 전자폭풍 수류탄\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 하이머딩거는 체력이 낮으므로 진입 성공 시 점화로 빠르게 마무리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_irelia);
if (typeof module !== 'undefined') module.exports = top_irelia;
